package renown

// Scale is the fixed-point scale of the decay table.
const Scale int64 = 1_000_000

// decaySteps holds 2^(-k/8) * Scale for k = 0..7, rounded to nearest.
var decaySteps = [8]int64{1_000_000, 917_004, 840_896, 771_105, 707_107, 648_420, 594_604, 545_254}

// Decay returns points after dt seconds of exponential decay with the given
// half-life. Whole half-lives are a right shift; the remainder is rounded
// down to the nearest eighth of a half-life and applied from a table. The
// result never increases with dt and is exact at every multiple of the
// half-life. Non-positive points return 0; a non-positive dt or half-life
// returns points unchanged.
func Decay(points, dt, halfLife int64) int64 {
	if points <= 0 {
		return 0
	}
	if dt <= 0 || halfLife <= 0 {
		return points
	}
	halves := dt / halfLife
	if halves >= 63 {
		return 0
	}
	p := points >> uint(halves)
	k := MulDiv(dt%halfLife, 8, halfLife) // 0..7
	return MulDiv(p, decaySteps[k], Scale)
}

package renown

const (
	maxInt64 int64 = 1<<63 - 1
	minInt64 int64 = -1 << 63
)

// SatAdd returns a+b, clamped to the int64 range instead of wrapping.
func SatAdd(a, b int64) int64 {
	if b > 0 && a > maxInt64-b {
		return maxInt64
	}
	if b < 0 && a < minInt64-b {
		return minInt64
	}
	return a + b
}

// SatMul returns a*b, clamped to the int64 range instead of wrapping.
func SatMul(a, b int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}
	neg := (a < 0) != (b < 0)
	if a == minInt64 || b == minInt64 {
		if neg {
			return minInt64
		}
		return maxInt64
	}
	ua, ub := a, b
	if ua < 0 {
		ua = -ua
	}
	if ub < 0 {
		ub = -ub
	}
	if ua > maxInt64/ub {
		if neg {
			return minInt64
		}
		return maxInt64
	}
	return a * b
}

// MulDiv returns x*num/den for x >= 0, num >= 0, den > 0 without the
// intermediate overflow of a naive x*num. The result saturates at the int64
// maximum. Invalid inputs return 0.
func MulDiv(x, num, den int64) int64 {
	if x <= 0 || num <= 0 || den <= 0 {
		return 0
	}
	q, r := x/den, x%den
	return SatAdd(SatMul(q, num), SatMul(r, num)/den)
}

// Min returns the smaller of a and b.
func Min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

// Package renown holds Barkeep's pure scoring math: categories, decay,
// multipliers and tiers. It has no state, no floats and no callbacks, so the
// algorithm is fixed for every version path and any realm can reuse it.
//
// Units: points are stored as milli-points (1 point = 1000 milli-points).
// Multipliers are expressed in permille (1000 = x1.0).
package renown

// Category names. A source realm declares exactly one. There is no
// balance-based category on purpose.
const (
	Governance   = "governance"
	Contribution = "contribution"
	DeFi         = "defi"
	Building     = "building"
	Community    = "community"
)

// NumCategories is the number of known categories.
const NumCategories = 5

var categories = [NumCategories]string{Governance, Contribution, DeFi, Building, Community}

// Categories returns the known categories in a stable order.
func Categories() []string {
	out := make([]string, NumCategories)
	for i, c := range categories {
		out[i] = c
	}
	return out
}

// CategoryIndex returns the stable index of c, or -1 when c is unknown.
func CategoryIndex(c string) int {
	for i, k := range categories {
		if k == c {
			return i
		}
	}
	return -1
}

// ValidCategory reports whether c is a known category.
func ValidCategory(c string) bool {
	return CategoryIndex(c) >= 0
}

// MaxKindLen bounds the length of an attestation kind.
const MaxKindLen = 32

// ValidKind reports whether kind is 1..MaxKindLen chars of [a-z0-9._-].
// The charset keeps kinds safe to print in markdown and JSON.
func ValidKind(kind string) bool {
	if len(kind) == 0 || len(kind) > MaxKindLen {
		return false
	}
	for i := 0; i < len(kind); i++ {
		c := kind[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

package renown

// Milli is the number of milli-points in one point.
const Milli int64 = 1000

// Permille is the multiplier value for x1.0.
const Permille int64 = 1000

// Params are the tunable constants of the score formula.
type Params struct {
	HalfLife          int64 // seconds for a bucket to lose half its points
	MaturityPeriod    int64 // seconds from the first verified attestation to full weight
	MaturityStart     int64 // permille applied at the first verified attestation
	IdentityBonus     int64 // permille applied when the address has a registered name
	DiversityStep     int64 // permille added per active category after the first
	DiversityMax      int64 // permille ceiling of the diversity multiplier
	DefaultWeight     int64 // permille weight given to a newly verified source
	MaxWeight         int64 // permille ceiling for a source weight
	DefaultCap        int64 // milli-points a source bucket may hold by default
	MaxUnitsPerAttest int64 // largest units value one attestation may carry
}

// DefaultParams returns the v0 parameters.
func DefaultParams() Params {
	return Params{
		HalfLife:          30 * 24 * 3600,
		MaturityPeriod:    7 * 24 * 3600,
		MaturityStart:     500,
		IdentityBonus:     1200,
		DiversityStep:     150,
		DiversityMax:      1600,
		DefaultWeight:     1000,
		MaxWeight:         3000,
		DefaultCap:        100 * Milli,
		MaxUnitsPerAttest: 100,
	}
}

// Valid reports whether every field is in a sane range.
func (p Params) Valid() bool {
	return p.HalfLife > 0 &&
		p.MaturityPeriod >= 0 &&
		p.MaturityStart > 0 && p.MaturityStart <= Permille &&
		p.IdentityBonus >= Permille &&
		p.DiversityStep >= 0 &&
		p.DiversityMax >= Permille &&
		p.DefaultWeight >= 0 && p.DefaultWeight <= p.MaxWeight &&
		p.DefaultCap > 0 &&
		p.MaxUnitsPerAttest > 0
}

// Bucket is the decaying balance one source holds for one address.
type Bucket struct {
	Points int64 // milli-points as of LastTs
	LastTs int64 // unix seconds of the last update
}

// At returns the bucket value at now.
func (b Bucket) At(now, halfLife int64) int64 {
	return Decay(b.Points, now-b.LastTs, halfLife)
}

// Accrue decays b to now, adds add milli-points and clamps to capacity.
// The cap applies to the balance, not to a time window.
func (b Bucket) Accrue(add, now, halfLife, capacity int64) Bucket {
	v := b.At(now, halfLife)
	if add > 0 {
		v = SatAdd(v, add)
	}
	return Bucket{Points: Min(v, capacity), LastTs: now}
}

// Weighted applies a permille weight to a value.
func Weighted(value, weight int64) int64 {
	return MulDiv(value, weight, Permille)
}

// Maturity returns the permille multiplier for an address whose first
// verified attestation happened at firstSeen. It ramps linearly from
// MaturityStart to 1000 over MaturityPeriod. firstSeen <= 0 means never.
func Maturity(firstSeen, now int64, p Params) int64 {
	if firstSeen <= 0 || now < firstSeen {
		return p.MaturityStart
	}
	elapsed := now - firstSeen
	if p.MaturityPeriod <= 0 || elapsed >= p.MaturityPeriod {
		return Permille
	}
	return p.MaturityStart + MulDiv(Permille-p.MaturityStart, elapsed, p.MaturityPeriod)
}

// Diversity returns the permille multiplier for the number of categories
// with a positive weighted score: 1000 + step*(n-1), at most DiversityMax.
func Diversity(activeCategories int, p Params) int64 {
	if activeCategories <= 1 {
		return Permille
	}
	return Min(SatAdd(Permille, SatMul(p.DiversityStep, int64(activeCategories-1))), p.DiversityMax)
}

// Identity returns the permille multiplier for a registered name.
func Identity(named bool, p Params) int64 {
	if named {
		return p.IdentityBonus
	}
	return Permille
}

// Composite combines the weighted base (milli-points) with the identity,
// maturity and diversity multipliers (permille) into milli-points.
func Composite(base, identity, maturity, diversity int64) int64 {
	s := MulDiv(base, maturity, Permille)
	s = MulDiv(s, diversity, Permille)
	return MulDiv(s, identity, Permille)
}

// ToPoints converts milli-points to whole points, rounding down.
func ToPoints(milli int64) int64 {
	if milli <= 0 {
		return 0
	}
	return milli / Milli
}

// Tier names.
const (
	Stranger = "Stranger"
	Regular  = "Regular"
	Patron   = "Patron"
	Legend   = "Legend"
)

// Tier thresholds in whole points.
const (
	RegularMin int64 = 10
	PatronMin  int64 = 100
	LegendMin  int64 = 500
)

// TierOf maps a whole-point score to a tier name.
func TierOf(score int64) string {
	switch {
	case score >= LegendMin:
		return Legend
	case score >= PatronMin:
		return Patron
	case score >= RegularMin:
		return Regular
	}
	return Stranger
}

package barkeep

import (
	"chain"
	"chain/runtime"
	"time"

	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
)

// Admin returns the current admin address.
func Admin() address { return admin }

// PendingAdmin returns the address that may accept the admin role.
func PendingAdmin() address { return pendingAdmin }

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("barkeep: caller is not the admin")
	}
}

func mustSource(path string) *source {
	s := sourceByPath(path)
	if s == nil {
		panic("barkeep: unknown source " + path)
	}
	return s
}

func logAction(action string, attrs ...string) {
	chain.Emit(action, attrs...)
	text := action
	for i := 0; i+1 < len(attrs); i += 2 {
		text += " " + attrs[i] + "=" + attrs[i+1]
	}
	e := logEntry{ts: time.Now().Unix(), height: runtime.ChainHeight(), action: text}
	if len(adminLog) < MaxAdminLog {
		adminLog = append(adminLog, e)
		return
	}
	for i := 1; i < len(adminLog); i++ {
		adminLog[i-1] = adminLog[i]
	}
	adminLog[len(adminLog)-1] = e
}

// SetSourceTier moves a source between unverified, verified and revoked.
// Verifying a source that has no weight gives it the default weight. A
// revoked or unverified source stops counting toward every score at once,
// because points are kept per source.
func SetSourceTier(cur realm, path, tier string) {
	assertAdmin(cur)
	s := mustSource(path)
	switch tier {
	case TierUnverified, TierVerified, TierRevoked:
	default:
		panic("barkeep: invalid tier " + tier)
	}
	if s.tier != TierVerified && tier == TierVerified {
		verifiedCount++
	} else if s.tier == TierVerified && tier != TierVerified {
		verifiedCount--
	}
	s.tier = tier
	if tier == TierVerified && s.weight == 0 {
		s.weight = params.DefaultWeight
	}
	logAction("SourceTierChanged", "source", path, "tier", tier)
}

// SetWeight sets a source's weight (permille, 0..MaxWeight) and bucket cap
// in whole points.
func SetWeight(cur realm, path string, weight, capPoints int64) {
	assertAdmin(cur)
	s := mustSource(path)
	if weight < 0 || weight > params.MaxWeight {
		panic("barkeep: weight out of range")
	}
	if capPoints <= 0 || capPoints > 1_000_000 {
		panic("barkeep: cap out of range")
	}
	s.weight = weight
	s.capacity = capPoints * renown.Milli
	logAction("SourceWeightChanged", "source", path, "weight", itoa(weight), "cap", itoa(capPoints))
}

// Pause stops or resumes attestations from one source. Existing points of
// a paused source keep counting and decaying.
func Pause(cur realm, path string, paused bool) {
	assertAdmin(cur)
	s := mustSource(path)
	s.paused = paused
	logAction("SourcePaused", "source", path, "paused", boolStr(paused))
}

// PauseAll stops or resumes every attestation.
func PauseAll(cur realm, paused bool) {
	assertAdmin(cur)
	pausedAll = paused
	logAction("BarkeepPaused", "paused", boolStr(paused))
}

// TransferAdmin proposes a new admin. The role moves only after the new
// address calls AcceptAdmin. Proposing the zero address cancels.
func TransferAdmin(cur realm, newAdmin address) {
	assertAdmin(cur)
	if newAdmin != "" && !newAdmin.IsValid() {
		panic("barkeep: invalid admin address")
	}
	pendingAdmin = newAdmin
	logAction("AdminProposed", "pending", newAdmin.String())
}

// AcceptAdmin completes a TransferAdmin.
func AcceptAdmin(cur realm) {
	caller := cur.Previous().Address()
	if pendingAdmin == "" || caller != pendingAdmin {
		panic("barkeep: caller is not the pending admin")
	}
	admin = caller
	pendingAdmin = ""
	logAction("AdminChanged", "admin", caller.String())
}

package barkeep

import (
	"chain"
	"strings"
	"time"

	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
)

// RegisterSource registers the calling code realm as an attestation source
// in one category. Registration is permissionless; new sources start
// unverified with weight 0 until an admin verifies them. It returns false
// when the caller is not a realm, the category or description is invalid,
// or the realm is already registered.
func RegisterSource(cur realm, category, desc string) bool {
	prev := cur.Previous()
	if !prev.IsCode() {
		return false
	}
	path := prev.PkgPath()
	if !strings.HasPrefix(path, "gno.land/r/") || sourceIDs.Has(path) {
		return false
	}
	if !renown.ValidCategory(category) || !ValidDesc(desc) {
		return false
	}
	s := &source{
		id:           nextID,
		path:         path,
		category:     category,
		desc:         desc,
		tier:         TierUnverified,
		capacity:     params.DefaultCap,
		registeredAt: time.Now().Unix(),
	}
	nextID++
	sourceIDs.Set(path, s.id)
	sourcesByID.Set(idKey(s.id), s)
	chain.Emit("SourceRegistered", "source", path, "category", category, "id", itoa(int64(s.id)))
	return true
}

// ValidDesc reports whether desc fits a source description: at most
// MaxDescLen bytes of printable ASCII without the markdown/HTML
// metacharacters [ ] ( ) < > ` | # * _ & and without URLs ("://" or
// "www."), so it cannot form links even before render escaping. Empty is
// allowed.
func ValidDesc(desc string) bool {
	if len(desc) > MaxDescLen {
		return false
	}
	lower := strings.ToLower(desc)
	if strings.Contains(lower, "://") || strings.Contains(lower, "www.") {
		return false
	}
	for i := 0; i < len(desc); i++ {
		c := desc[i]
		if c < 0x20 || c > 0x7e {
			return false
		}
		switch c {
		case '[', ']', '(', ')', '<', '>', '`', '|', '#', '*', '_', '&':
			return false
		}
	}
	return true
}

// Attest credits units to subject on behalf of the calling source realm.
//
// It never panics for ordinary conditions, so Barkeep cannot fail a source
// realm's transaction: it returns false when the caller is not a registered
// realm, the source is revoked or paused, Barkeep is paused, the subject is
// the source itself or invalid, the kind is malformed, or units is outside
// 1..MaxUnitsPerAttest. Attestations from unverified sources are recorded
// on existing profiles but weigh 0 until the source is verified; a source
// with no effective weight cannot create a profile, so an unverified realm
// cannot make signers pay storage for profiles of arbitrary addresses.
func Attest(cur realm, subject address, kind string, units int64) bool {
	prev := cur.Previous()
	if !prev.IsCode() || pausedAll {
		return false
	}
	s := sourceByPath(prev.PkgPath())
	if s == nil || s.paused || s.tier == TierRevoked {
		return false
	}
	if !subject.IsValid() || subject == prev.Address() {
		return false
	}
	if !renown.ValidKind(kind) || units <= 0 || units > params.MaxUnitsPerAttest {
		return false
	}

	now := time.Now().Unix()
	key := subject.String()
	p := profileOf(subject)
	if p == nil {
		if s.effectiveWeight() == 0 {
			return false
		}
		p = &profile{}
		profiles.Set(key, p)
	}
	if !p.accrue(s, units*renown.Milli, now) {
		return false
	}
	if p.firstSeen == 0 && s.effectiveWeight() > 0 {
		p.firstSeen = now
	}
	p.pushRecent(recentEntry{src: s.id, kind: kind, units: units, ts: now})
	p.attestations++
	s.attestations++
	attestations++

	updateTop(subject, computeScore(subject, p, now).total, now)
	chain.Emit("Attested",
		"subject", key,
		"source", s.path,
		"kind", kind,
		"units", itoa(units),
	)
	return true
}

// accrue adds milli-points to the bucket of source s. When the profile
// already holds MaxBuckets sources, the lowest-ranked bucket is replaced
// only if it ranks below the new one, so unverified spam cannot evict
// verified history. It returns false when nothing was stored.
func (p *profile) accrue(s *source, add, now int64) bool {
	for i := range p.buckets {
		if p.buckets[i].src == s.id {
			p.buckets[i].b = p.buckets[i].b.Accrue(add, now, params.HalfLife, s.capacity)
			return true
		}
	}
	nb := bucket{src: s.id, b: renown.Bucket{}.Accrue(add, now, params.HalfLife, s.capacity)}
	if len(p.buckets) < MaxBuckets {
		p.buckets = append(p.buckets, nb)
		return true
	}
	worst := 0
	for i := 1; i < len(p.buckets); i++ {
		if bucketLess(p.buckets[i], p.buckets[worst], now) {
			worst = i
		}
	}
	if !bucketLess(p.buckets[worst], nb, now) {
		return false
	}
	p.buckets[worst] = nb
	return true
}

// bucketLess ranks buckets: weightless before weighted, then by weighted
// value, then by raw value.
func bucketLess(a, b bucket, now int64) bool {
	wa, va := bucketRank(a, now)
	wb, vb := bucketRank(b, now)
	if (wa > 0) != (wb > 0) {
		return wa == 0
	}
	if xa, xb := renown.Weighted(va, wa), renown.Weighted(vb, wb); xa != xb {
		return xa < xb
	}
	return va < vb
}

// bucketRank returns the effective weight and capped value of b; a bucket
// whose source is gone ranks lowest.
func bucketRank(b bucket, now int64) (int64, int64) {
	s := sourceByID(b.src)
	if s == nil {
		return 0, 0
	}
	return s.effectiveWeight(), b.value(s, now)
}

func (p *profile) pushRecent(e recentEntry) {
	if len(p.recent) < MaxRecent {
		p.recent = append(p.recent, e)
		return
	}
	for i := 1; i < len(p.recent); i++ {
		p.recent[i-1] = p.recent[i]
	}
	p.recent[len(p.recent)-1] = e
}

// updateTop keeps the top-MaxTop addresses by score snapshot. Snapshots go
// stale as points decay, sources are revoked or names are registered. A
// full refresh costs MaxTop score computations (~70M gas on chain, each
// one reads r/sys/users), so the work is bounded per call instead: when a
// newcomer meets a full board, TopRefreshBatch snapshots are refreshed in
// rotation (every entry within MaxTop/TopRefreshBatch newcomers), and the
// eviction candidate is re-scored before it is replaced, so a snapshot
// that is too low never costs a member its slot.
func updateTop(addr address, score, now int64) {
	for i := range top {
		if top[i].addr == addr {
			top[i].snap = score
			return
		}
	}
	if score <= 0 {
		return
	}
	if len(top) < MaxTop {
		top = append(top, topEntry{addr: addr, snap: score})
		return
	}
	for j := 0; j < TopRefreshBatch; j++ {
		topCursor %= len(top)
		refreshSnap(topCursor, now)
		topCursor++
	}
	// Only a candidate whose snapshot was just recomputed is evicted.
	worst, fresh := worstTop(), -1
	for j := 0; j < TopConfirmMax && worst != fresh && score > top[worst].snap; j++ {
		refreshSnap(worst, now)
		fresh, worst = worst, worstTop()
	}
	if worst == fresh && score > top[worst].snap {
		top[worst] = topEntry{addr: addr, snap: score}
	}
}

func refreshSnap(i int, now int64) {
	top[i].snap = computeScore(top[i].addr, profileOf(top[i].addr), now).total
}

func worstTop() int {
	worst := 0
	for i := range top {
		if top[i].snap < top[worst].snap {
			worst = i
		}
	}
	return worst
}

// Package barkeep is a cross-realm reputation registry for gno.land.
//
// Registered source realms attest activity with a crossing call:
//
//	barkeep.Attest(cross(cur), subject, "quest.completed", 1)
//
// The source is identified by cur.Previous().PkgPath(), which the VM sets and
// a caller cannot forge. Scores decay over time, are capped per source and
// only count sources an admin has verified. All math lives in
// gno.land/p/<ns>/renown/v0. Reads are non-crossing and return values or
// strings, never pointers into realm state.
package barkeep

import (
	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
	"gno.land/p/nt/avl/v0"
)

// Source tiers.
const (
	TierUnverified = "unverified"
	TierVerified   = "verified"
	TierRevoked    = "revoked"
)

// Limits.
const (
	MaxBuckets   = 32  // sources tracked per profile
	MaxRecent    = 10  // recent attestations kept per profile
	MaxTop       = 50  // leaderboard size
	MaxDescLen   = 140 // source description length, printable ASCII
	MaxAdminLog  = 20  // admin log entries kept on chain
	MaxPageLimit = 50  // largest page served by the JSON readers

	TopRefreshBatch = 2 // leaderboard snapshots refreshed per newcomer on a full board
	TopConfirmMax   = 2 // eviction candidates re-scored before one is replaced
)

type source struct {
	id           int
	path         string
	category     string
	desc         string
	tier         string
	weight       int64 // permille, effective only while verified
	capacity     int64 // milli-points a bucket may hold
	paused       bool
	registeredAt int64
	attestations int64
}

// effectiveWeight is the weight that counts toward scores.
func (s *source) effectiveWeight() int64 {
	if s.tier != TierVerified {
		return 0
	}
	return s.weight
}

type bucket struct {
	src int
	b   renown.Bucket
}

// value is the decayed milli-points of bk at now, clamped to the source's
// current cap so a lowered cap applies at once, not only on the next
// attestation.
func (bk bucket) value(s *source, now int64) int64 {
	return renown.Min(bk.b.At(now, params.HalfLife), s.capacity)
}

type recentEntry struct {
	src   int
	kind  string
	units int64
	ts    int64
}

type profile struct {
	firstSeen    int64 // first attestation from a verified source, 0 if none
	buckets      []bucket
	recent       []recentEntry // oldest first
	attestations int64
}

type topEntry struct {
	addr address
	snap int64 // milli-points when last updated; reads recompute
}

type logEntry struct {
	ts     int64
	height int64
	action string
}

var (
	params = renown.DefaultParams()

	admin        address = "g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p"
	pendingAdmin address
	pausedAll    bool

	sourceIDs     = avl.NewTree() // pkgpath -> int id
	sourcesByID   = avl.NewTree() // padded id -> *source
	nextID        = 1
	verifiedCount int             // sources currently in TierVerified
	profiles      = avl.NewTree() // address string -> *profile

	top          []topEntry
	topCursor    int // next snapshot refreshed by the rolling refresh
	attestations int64
	adminLog     []logEntry
)

func idKey(id int) string {
	s := itoa(int64(id))
	for len(s) < 8 {
		s = "0" + s
	}
	return s
}

func sourceByID(id int) *source {
	if v := sourcesByID.Get(idKey(id)); v != nil {
		return v.(*source)
	}
	return nil
}

func sourceByPath(path string) *source {
	if v := sourceIDs.Get(path); v != nil {
		return sourceByID(v.(int))
	}
	return nil
}

func profileOf(addr address) *profile {
	if v := profiles.Get(addr.String()); v != nil {
		return v.(*profile)
	}
	return nil
}

package barkeep

import (
	"strings"
	"unicode/utf8"

	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
)

const hexDigits = "0123456789abcdef"

// jsonStr quotes s as a JSON string. It is safe for any byte sequence:
// control bytes, DEL, < > & and U+2028/U+2029 are \u-escaped, and invalid
// UTF-8 becomes U+FFFD, so the output is always valid JSON that can be
// embedded in HTML or JavaScript.
func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); {
		c := s[i]
		if c >= utf8.RuneSelf {
			r, size := utf8.DecodeRuneInString(s[i:])
			switch {
			case r == utf8.RuneError && size == 1:
				b.WriteString("\\ufffd")
			case r == ' ':
				b.WriteString("\\u2028")
			case r == ' ':
				b.WriteString("\\u2029")
			default:
				b.WriteString(s[i : i+size])
			}
			i += size
			continue
		}
		switch {
		case c == '"' || c == '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c == '\n':
			b.WriteString("\\n")
		case c < 0x20 || c == 0x7f || c == '<' || c == '>' || c == '&':
			b.WriteString("\\u00")
			b.WriteByte(hexDigits[c>>4])
			b.WriteByte(hexDigits[c&0xf])
		default:
			b.WriteByte(c)
		}
		i++
	}
	b.WriteByte('"')
	return b.String()
}

// jsonObj builds an object from alternating keys and raw JSON values.
func jsonObj(kv ...string) string {
	var b strings.Builder
	b.WriteByte('{')
	for i := 0; i+1 < len(kv); i += 2 {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonStr(kv[i]))
		b.WriteByte(':')
		b.WriteString(kv[i+1])
	}
	b.WriteByte('}')
	return b.String()
}

func jsonArr(items []string) string {
	return "[" + strings.Join(items, ",") + "]"
}

func sourceJSON(s *source) string {
	return jsonObj(
		"id", itoa(int64(s.id)),
		"path", jsonStr(s.path),
		"category", jsonStr(s.category),
		"desc", jsonStr(s.desc),
		"tier", jsonStr(s.tier),
		"weight", itoa(s.weight),
		"effectiveWeight", itoa(s.effectiveWeight()),
		"capPoints", itoa(renown.ToPoints(s.capacity)),
		"paused", boolStr(s.paused),
		"registeredAt", itoa(s.registeredAt),
		"attestations", itoa(s.attestations),
	)
}

func sourcePath(id int) string {
	if s := sourceByID(id); s != nil {
		return s.path
	}
	return ""
}

// ProfileJSON returns the full score breakdown of addr as JSON. Point
// values are decimals with three fraction digits.
func ProfileJSON(addr address) string {
	t := now()
	p := profileOf(addr)
	r := computeScore(addr, p, t)
	cats := make([]string, 0, renown.NumCategories)
	for i, c := range renown.Categories() {
		cats = append(cats, jsonStr(c)+":"+milliStr(r.cats[i]))
	}
	var buckets, recent []string
	firstSeen, count := int64(0), int64(0)
	if p != nil {
		firstSeen, count = p.firstSeen, p.attestations
		for _, bk := range p.buckets {
			s := sourceByID(bk.src)
			if s == nil {
				continue
			}
			v := bk.value(s, t)
			buckets = append(buckets, jsonObj(
				"source", jsonStr(s.path),
				"category", jsonStr(s.category),
				"tier", jsonStr(s.tier),
				"points", milliStr(v),
				"weighted", milliStr(renown.Weighted(v, s.effectiveWeight())),
				"lastTs", itoa(bk.b.LastTs),
			))
		}
		for i := len(p.recent) - 1; i >= 0; i-- {
			e := p.recent[i]
			recent = append(recent, jsonObj(
				"source", jsonStr(sourcePath(e.src)),
				"kind", jsonStr(e.kind),
				"units", itoa(e.units),
				"ts", itoa(e.ts),
			))
		}
	}
	score := renown.ToPoints(r.total)
	return jsonObj(
		"address", jsonStr(addr.String()),
		"score", itoa(score),
		"tier", jsonStr(renown.TierOf(score)),
		"total", milliStr(r.total),
		"base", milliStr(r.base),
		"multipliers", jsonObj(
			"identity", milliStr(r.identity),
			"maturity", milliStr(r.maturity),
			"diversity", milliStr(r.diversity),
		),
		"named", boolStr(r.identity > renown.Permille),
		"activeCategories", itoa(int64(r.active)),
		"categories", "{"+strings.Join(cats, ",")+"}",
		"firstSeen", itoa(firstSeen),
		"attestations", itoa(count),
		"buckets", jsonArr(buckets),
		"recent", jsonArr(recent),
		"now", itoa(t),
	)
}

// LeaderboardJSON returns a page of the top-50 leaderboard, recomputed at
// read time. limit is capped at MaxPageLimit.
func LeaderboardJSON(offset, limit int) string {
	t := now()
	rows := leaderboard(t)
	start, end := page(len(rows), offset, limit)
	items := make([]string, 0, end-start)
	for i := start; i < end; i++ {
		score := renown.ToPoints(rows[i].score)
		items = append(items, jsonObj(
			"rank", itoa(int64(i+1)),
			"address", jsonStr(rows[i].addr.String()),
			"score", itoa(score),
			"tier", jsonStr(renown.TierOf(score)),
		))
	}
	return jsonObj(
		"total", itoa(int64(len(rows))),
		"offset", itoa(int64(start)),
		"profiles", itoa(int64(profiles.Size())),
		"attestations", itoa(attestations),
		"items", jsonArr(items),
		"now", itoa(t),
	)
}

// SourcesJSON returns a page of registered sources in registration order.
// limit is capped at MaxPageLimit.
func SourcesJSON(offset, limit int) string {
	n := sourcesByID.Size()
	start, end := page(n, offset, limit)
	items := make([]string, 0, end-start)
	sourcesByID.IterateByOffset(start, end-start, func(_ string, v any) bool {
		items = append(items, sourceJSON(v.(*source)))
		return false
	})
	return jsonObj(
		"total", itoa(int64(n)),
		"offset", itoa(int64(start)),
		"items", jsonArr(items),
	)
}

// ParamsJSON returns the live algorithm parameters.
func ParamsJSON() string {
	p := params
	return jsonObj(
		"halfLifeSeconds", itoa(p.HalfLife),
		"maturityPeriodSeconds", itoa(p.MaturityPeriod),
		"maturityStart", milliStr(p.MaturityStart),
		"identityBonus", milliStr(p.IdentityBonus),
		"diversityStep", milliStr(p.DiversityStep),
		"diversityMax", milliStr(p.DiversityMax),
		"defaultWeight", milliStr(p.DefaultWeight),
		"maxWeight", milliStr(p.MaxWeight),
		"defaultCapPoints", itoa(renown.ToPoints(p.DefaultCap)),
		"maxUnitsPerAttest", itoa(p.MaxUnitsPerAttest),
		"maxBuckets", itoa(MaxBuckets),
		"maxRecent", itoa(MaxRecent),
		"maxTop", itoa(MaxTop),
		"tiers", jsonObj(
			"Regular", itoa(renown.RegularMin),
			"Patron", itoa(renown.PatronMin),
			"Legend", itoa(renown.LegendMin),
		),
		"paused", boolStr(pausedAll),
		"admin", jsonStr(admin.String()),
	)
}

package barkeep

import (
	"strconv"
	"time"

	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
	"gno.land/r/sys/users"
)

// breakdown is the score of one address at one instant, in milli-points.
type breakdown struct {
	total     int64
	base      int64
	cats      [renown.NumCategories]int64
	active    int
	identity  int64
	maturity  int64
	diversity int64
}

func hasName(addr address) bool {
	return users.ResolveAddress(addr) != nil
}

// computeScore applies the Barkeep formula:
//
//	Score = M_identity * M_maturity * M_diversity * sum_s(w_s * decay(bucket_s))
func computeScore(addr address, p *profile, now int64) breakdown {
	var r breakdown
	r.identity = renown.Identity(hasName(addr), params)
	if p == nil {
		r.maturity, r.diversity = params.MaturityStart, renown.Permille
		return r
	}
	for _, bk := range p.buckets {
		s := sourceByID(bk.src)
		if s == nil {
			continue
		}
		w := s.effectiveWeight()
		if w == 0 {
			continue
		}
		v := renown.Weighted(bk.value(s, now), w)
		ci := renown.CategoryIndex(s.category)
		r.cats[ci] = renown.SatAdd(r.cats[ci], v)
		r.base = renown.SatAdd(r.base, v)
	}
	for _, c := range r.cats {
		if c >= renown.Milli { // a category counts once it holds a whole point
			r.active++
		}
	}
	r.maturity = renown.Maturity(p.firstSeen, now, params)
	r.diversity = renown.Diversity(r.active, params)
	r.total = renown.Composite(r.base, r.identity, r.maturity, r.diversity)
	return r
}

func now() int64 { return time.Now().Unix() }

// ScoreOf returns the composite score of addr in whole points.
func ScoreOf(addr address) int64 {
	return renown.ToPoints(computeScore(addr, profileOf(addr), now()).total)
}

// CategoryScoreOf returns the weighted, decayed points addr holds in one
// category, before multipliers. Unknown categories return 0.
func CategoryScoreOf(addr address, category string) int64 {
	ci := renown.CategoryIndex(category)
	if ci < 0 {
		return 0
	}
	return renown.ToPoints(computeScore(addr, profileOf(addr), now()).cats[ci])
}

// SourceScoreOf returns the decayed, unweighted points addr holds from one
// source, so unverified sources are visible too.
func SourceScoreOf(addr address, path string) int64 {
	p, s := profileOf(addr), sourceByPath(path)
	if p == nil || s == nil {
		return 0
	}
	for _, bk := range p.buckets {
		if bk.src == s.id {
			return renown.ToPoints(bk.value(s, now()))
		}
	}
	return 0
}

// TierOf returns the tier name of addr.
func TierOf(addr address) string {
	return renown.TierOf(ScoreOf(addr))
}

// HasMinScore reports whether addr has at least min whole points. Consumer
// realms gate on it: if !barkeep.HasMinScore(caller, 100) { panic(...) }.
func HasMinScore(addr address, min int64) bool {
	return ScoreOf(addr) >= min
}

// HasMinCategoryScore reports whether addr has at least min weighted points
// in one category.
func HasMinCategoryScore(addr address, category string, min int64) bool {
	return CategoryScoreOf(addr, category) >= min
}

// IsPaused reports whether every attestation is paused.
func IsPaused() bool { return pausedAll }

// SourceTier returns the tier of a source, or "" when unknown.
func SourceTier(path string) string {
	if s := sourceByPath(path); s != nil {
		return s.tier
	}
	return ""
}

// ranked is one leaderboard row.
type ranked struct {
	addr  address
	score int64 // milli-points
}

// leaderboard recomputes the cached top entries at now, sorted by score
// descending, then address for stability.
func leaderboard(t int64) []ranked {
	rows := make([]ranked, 0, len(top))
	for _, e := range top {
		s := computeScore(e.addr, profileOf(e.addr), t).total
		if s >= renown.Milli {
			rows = append(rows, ranked{addr: e.addr, score: s})
		}
	}
	for i := 1; i < len(rows); i++ {
		for j := i; j > 0 && rankedBefore(rows[j], rows[j-1]); j-- {
			rows[j], rows[j-1] = rows[j-1], rows[j]
		}
	}
	return rows
}

func rankedBefore(a, b ranked) bool {
	if a.score != b.score {
		return a.score > b.score
	}
	return a.addr < b.addr
}

func page(n, offset, limit int) (int, int) {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > MaxPageLimit {
		limit = MaxPageLimit
	}
	if offset > n {
		offset = n
	}
	end := offset + limit
	if end > n {
		end = n
	}
	return offset, end
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// milliStr formats milli-points or permille as a decimal with 3 digits.
func milliStr(v int64) string {
	neg := v < 0
	if neg {
		v = -v
	}
	frac := itoa(v % 1000)
	for len(frac) < 3 {
		frac = "0" + frac
	}
	s := itoa(v/1000) + "." + frac
	if neg {
		return "-" + s
	}
	return s
}

package barkeep

import (
	"strconv"
	"strings"

	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

const renderPageSize = 20

// Render serves gnoweb pages: "" (leaderboard), "u/<addr>", "sources",
// "algorithm" and "integrate". Lists accept "?page=N". The path is
// attacker-controlled: it is parsed, never echoed raw.
func Render(path string) string {
	route, query, _ := strings.Cut(path, "?")
	pg := pageParam(query)
	switch {
	case route == "":
		return renderHome(pg)
	case strings.HasPrefix(route, "u/"):
		return renderProfile(strings.TrimPrefix(route, "u/"))
	case route == "sources":
		return renderSources(pg)
	case route == "algorithm":
		return renderAlgorithm()
	case route == "integrate":
		return renderIntegrate()
	}
	return "# Not found\n\n[Back to the bar](/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0)\n"
}

func pageParam(query string) int {
	for _, kv := range strings.Split(query, "&") {
		if v, ok := strings.CutPrefix(kv, "page="); ok {
			if n, err := strconv.Atoi(v); err == nil && n > 0 && n < 1_000_000 {
				return n
			}
		}
	}
	return 1
}

func cell(s string) string { return sanitize.TableCell(s) }

func nav() string {
	return "[Leaderboard](:) · [Sources](:sources) · [Algorithm](:algorithm) · [Integrate](:integrate)\n\n"
}

func pager(route string, pg, total int) string {
	pages := (total + renderPageSize - 1) / renderPageSize
	if pages <= 1 {
		return ""
	}
	out := "\nPage " + itoa(int64(pg)) + " of " + itoa(int64(pages))
	if pg > 1 {
		out += " · [Prev](:" + route + "?page=" + itoa(int64(pg-1)) + ")"
	}
	if pg < pages {
		out += " · [Next](:" + route + "?page=" + itoa(int64(pg+1)) + ")"
	}
	return out + "\n"
}

func renderHome(pg int) string {
	t := now()
	rows := leaderboard(t)
	var b strings.Builder
	b.WriteString("# Barkeep\n\n> The barkeep knows everyone's reputation.\n\n")
	b.WriteString(nav())
	b.WriteString("Profiles: " + itoa(int64(profiles.Size())) +
		" · Attestations: " + itoa(attestations) +
		" · Sources: " + itoa(int64(sourcesByID.Size())) + " (" + itoa(int64(verifiedCount)) + " verified)")
	if pausedAll {
		b.WriteString(" · **Paused**")
	}
	b.WriteString("\n\n## Leaderboard\n\n")
	if len(rows) == 0 {
		b.WriteString("Nobody has earned renown yet.\n")
		return b.String()
	}
	b.WriteString("| # | Address | Score | Tier |\n|---|---|---|---|\n")
	start, end := page(len(rows), (pg-1)*renderPageSize, renderPageSize)
	for i := start; i < end; i++ {
		a := rows[i].addr.String()
		score := renown.ToPoints(rows[i].score)
		b.WriteString("| " + itoa(int64(i+1)) + " | [" + a + "](:u/" + a + ") | " +
			itoa(score) + " | " + renown.TierOf(score) + " |\n")
	}
	b.WriteString(pager("", pg, len(rows)))
	return b.String()
}

func renderProfile(raw string) string {
	addr := address(raw)
	if !addr.IsValid() {
		return "# Unknown patron\n\nThat is not a valid address.\n\n" + nav()
	}
	t := now()
	p := profileOf(addr)
	r := computeScore(addr, p, t)
	score := renown.ToPoints(r.total)
	a := addr.String()
	var b strings.Builder
	b.WriteString("# Patron " + a + "\n\n" + nav())
	b.WriteString("**Score " + itoa(score) + "** · " + renown.TierOf(score) + "\n\n")
	b.WriteString("Base " + milliStr(r.base) + " × identity " + milliStr(r.identity) +
		" × maturity " + milliStr(r.maturity) + " × diversity " + milliStr(r.diversity) +
		" (" + itoa(int64(r.active)) + " categories)\n\n")
	if p == nil {
		b.WriteString("No attestations yet.\n")
		return b.String()
	}
	b.WriteString("## By source\n\n| Source | Category | Tier | Points | Weighted |\n|---|---|---|---|---|\n")
	for _, bk := range p.buckets {
		s := sourceByID(bk.src)
		if s == nil {
			continue
		}
		v := bk.value(s, t)
		b.WriteString("| " + cell(s.path) + " | " + s.category + " | " + s.tier + " | " +
			milliStr(v) + " | " + milliStr(renown.Weighted(v, s.effectiveWeight())) + " |\n")
	}
	b.WriteString("\n## Recent\n\n| Time (unix) | Source | Kind | Units |\n|---|---|---|---|\n")
	for i := len(p.recent) - 1; i >= 0; i-- {
		e := p.recent[i]
		b.WriteString("| " + itoa(e.ts) + " | " + cell(sourcePath(e.src)) + " | " + cell(e.kind) + " | " + itoa(e.units) + " |\n")
	}
	return b.String()
}

func renderSources(pg int) string {
	var b strings.Builder
	b.WriteString("# Sources\n\n" + nav())
	b.WriteString("Any realm may register; only **verified** sources count toward scores.\n\n")
	n := sourcesByID.Size()
	if n == 0 {
		b.WriteString("No sources yet.\n")
	} else {
		b.WriteString("| # | Realm | Category | Tier | Weight | Cap | Attestations | Description |\n|---|---|---|---|---|---|---|---|\n")
		start, end := page(n, (pg-1)*renderPageSize, renderPageSize)
		sourcesByID.IterateByOffset(start, end-start, func(_ string, v any) bool {
			s := v.(*source)
			tier := s.tier
			if s.paused {
				tier += " (paused)"
			}
			b.WriteString("| " + itoa(int64(s.id)) + " | " + cell(s.path) + " | " + s.category + " | " + tier + " | " +
				milliStr(s.effectiveWeight()) + " | " + itoa(renown.ToPoints(s.capacity)) + " | " +
				itoa(s.attestations) + " | " + cell(s.desc) + " |\n")
			return false
		})
		b.WriteString(pager("sources", pg, n))
	}
	b.WriteString("\n## Admin log\n\nAdmin: " + admin.String() + "\n\n")
	if len(adminLog) == 0 {
		b.WriteString("No admin actions yet.\n")
	}
	for i := len(adminLog) - 1; i >= 0; i-- {
		e := adminLog[i]
		b.WriteString("- height " + itoa(e.height) + " (" + itoa(e.ts) + "): " + sanitize.InlineText(e.action) + "\n")
	}
	return b.String()
}

func renderAlgorithm() string {
	p := params
	day := int64(24 * 3600)
	return "# Algorithm\n\n" + nav() +
		"```\nbucket_s(t) = min(cap_s, decay(points_s, t - last_s))\n" +
		"Score = M_identity × M_maturity × M_diversity × Σ_s w_s · bucket_s(t)\n```\n\n" +
		"| Parameter | Value |\n|---|---|\n" +
		"| Half-life | " + itoa(p.HalfLife/day) + " days |\n" +
		"| Decay | shift per half-life + 8-step table 2^(-k/8), fixed-point 1e6 |\n" +
		"| Default cap per source | " + itoa(renown.ToPoints(p.DefaultCap)) + " points |\n" +
		"| Max units per attestation | " + itoa(p.MaxUnitsPerAttest) + " |\n" +
		"| Identity (r/sys/users name) | ×" + milliStr(p.IdentityBonus) + " |\n" +
		"| Maturity | ×" + milliStr(p.MaturityStart) + " → ×1.000 over " + itoa(p.MaturityPeriod/day) + " days from the first verified attestation |\n" +
		"| Diversity | ×(1 + " + milliStr(p.DiversityStep) + " × (categories − 1)), max ×" + milliStr(p.DiversityMax) + " |\n" +
		"| Unverified source weight | 0 |\n" +
		"| Tiers | Regular ≥ " + itoa(renown.RegularMin) + ", Patron ≥ " + itoa(renown.PatronMin) + ", Legend ≥ " + itoa(renown.LegendMin) + " |\n\n" +
		"Categories: " + strings.Join(renown.Categories(), ", ") + ". No balance-based category.\n"
}

func renderIntegrate() string {
	return "# Integrate\n\n" + nav() +
		"## Source realm\n\n```go\nimport \"gno.land/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0\"\n\n" +
		"func init(cur realm) {\n\tbarkeep.RegisterSource(cross(cur), \"contribution\", \"Quests for adventurers\")\n}\n\n" +
		"func Complete(cur realm, id string) {\n\t// ... your logic\n\tbarkeep.Attest(cross(cur), cur.Previous().Address(), \"quest.completed\", 1)\n}\n```\n\n" +
		"`Attest` returns false instead of panicking, so Barkeep never fails your transaction.\n\n" +
		"## Consumer realm\n\n```go\nif !barkeep.HasMinScore(caller, 100) {\n\tpanic(\"not enough renown\")\n}\n```\n\n" +
		"Reads: `ScoreOf`, `CategoryScoreOf`, `SourceScoreOf`, `TierOf`, `HasMinScore`, `HasMinCategoryScore`, " +
		"`ProfileJSON`, `LeaderboardJSON(offset, limit)`, `SourcesJSON(offset, limit)`, `ParamsJSON`.\n"
}

// Package questboard is a dummy source realm used by Barkeep tests.
package questboard

import "gno.land/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0"

var completed int

func init(cur realm) {
	barkeep.RegisterSource(cross(cur), "contribution", "Quests for adventurers")
}

// Complete marks a quest done and attests the caller in Barkeep.
func Complete(cur realm, id string) bool {
	completed++
	return barkeep.Attest(cross(cur), cur.Previous().Address(), "quest.completed", 10)
}

// Completed returns how many quests were completed.
func Completed() int { return completed }

// Package townhall is a demo Barkeep realm that is both a consumer and a
// source: creating a poll requires renown, and every vote attests the voter
// in the governance category.
package townhall

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0"
)

const (
	// MinScoreToCreatePoll is the Barkeep score (whole points) a caller
	// needs to open a poll. Voting is open to everyone.
	MinScoreToCreatePoll int64 = 20

	MaxQuestionLen = 140
	MaxOptionLen   = 40
	MinOptions     = 2
	MaxOptions     = 5
	OptionSep      = "|"
	PageSize       = 10
)

type poll struct {
	id       int
	author   address
	question string
	options  []string
	votes    []int64
	voters   *avl.Tree // address -> option index
	height   int64
}

var (
	polls  = avl.NewTree() // padded id -> *poll
	nextID = 1
)

func init(cur realm) {
	barkeep.RegisterSource(cross(cur), "governance", "Town hall polls: one attestation per vote")
}

// CreatePoll opens a poll. options is a "|"-separated list of 2 to 5
// choices, so the function stays callable from gnokey. It panics when the
// caller lacks renown or the input is invalid.
func CreatePoll(cur realm, question, options string) int {
	caller := cur.Previous().Address()
	if !barkeep.HasMinScore(caller, MinScoreToCreatePoll) {
		panic("townhall: need a Barkeep score of at least " + strconv.FormatInt(MinScoreToCreatePoll, 10))
	}
	question = strings.TrimSpace(question)
	if !validText(question, MaxQuestionLen) {
		panic("townhall: question must be 1-140 printable ASCII characters")
	}
	opts := strings.Split(options, OptionSep)
	if len(opts) < MinOptions || len(opts) > MaxOptions {
		panic("townhall: a poll needs 2 to 5 options separated by |")
	}
	for i, o := range opts {
		opts[i] = strings.TrimSpace(o)
		if !validText(opts[i], MaxOptionLen) {
			panic("townhall: each option must be 1-40 printable ASCII characters")
		}
	}
	id := nextID
	nextID++
	polls.Set(key(id), &poll{
		id:       id,
		author:   caller,
		question: question,
		options:  opts,
		votes:    make([]int64, len(opts)),
		voters:   avl.NewTree(),
		height:   runtime.ChainHeight(),
	})
	return id
}

// Vote records one vote per address per poll and attests the voter in
// Barkeep. It returns whether Barkeep accepted the attestation; the vote
// counts either way. It panics on an unknown poll, a bad option or a
// second vote.
func Vote(cur realm, pollID, option int) bool {
	voter := cur.Previous().Address()
	p := getPoll(pollID)
	if p == nil {
		panic("townhall: unknown poll")
	}
	if option < 0 || option >= len(p.options) {
		panic("townhall: option out of range")
	}
	if p.voters.Has(voter.String()) {
		panic("townhall: already voted")
	}
	p.voters.Set(voter.String(), option)
	p.votes[option]++
	return barkeep.Attest(cross(cur), voter, "vote.cast", 1)
}

// PollCount returns how many polls exist.
func PollCount() int { return polls.Size() }

// VotesOf returns the tally of one option, or -1 when it does not exist.
func VotesOf(pollID, option int) int64 {
	p := getPoll(pollID)
	if p == nil || option < 0 || option >= len(p.options) {
		return -1
	}
	return p.votes[option]
}

// HasVoted reports whether addr voted in a poll.
func HasVoted(pollID int, addr address) bool {
	p := getPoll(pollID)
	return p != nil && p.voters.Has(addr.String())
}

// Render serves "" (polls, newest first, "?page=N") and "poll/<id>".
func Render(path string) string {
	route, query, _ := strings.Cut(path, "?")
	if rest, ok := strings.CutPrefix(route, "poll/"); ok {
		id, err := strconv.Atoi(rest)
		if err != nil {
			return notFound()
		}
		p := getPoll(id)
		if p == nil {
			return notFound()
		}
		return renderPoll(p)
	}
	if route != "" {
		return notFound()
	}
	return renderList(pageParam(query))
}

func renderList(pg int) string {
	var b strings.Builder
	b.WriteString("# Town Hall\n\nPolls by patrons of the tavern. Opening a poll needs a [Barkeep](/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0) score of ")
	b.WriteString(strconv.FormatInt(MinScoreToCreatePoll, 10))
	b.WriteString("; every vote earns governance renown.\n\n")
	total := polls.Size()
	if total == 0 {
		b.WriteString("_No polls yet._\n")
		return b.String()
	}
	pages := (total + PageSize - 1) / PageSize
	if pg > pages {
		pg = pages
	}
	b.WriteString("| # | Question | Votes |\n|---|---|---|\n")
	// Newest first: index total-1 is the latest poll.
	start := total - pg*PageSize
	count := PageSize
	if start < 0 {
		count += start
		start = 0
	}
	rows := make([]*poll, 0, count)
	polls.IterateByOffset(start, count, func(_ string, v any) bool {
		rows = append(rows, v.(*poll))
		return false
	})
	for i := len(rows) - 1; i >= 0; i-- {
		p := rows[i]
		id := strconv.Itoa(p.id)
		b.WriteString("| [" + id + "](:poll/" + id + ") | " + sanitize.TableCell(p.question) + " | " + strconv.FormatInt(int64(p.voters.Size()), 10) + " |\n")
	}
	if pages > 1 {
		b.WriteString("\nPage " + strconv.Itoa(pg) + " of " + strconv.Itoa(pages))
		if pg > 1 {
			b.WriteString(" · [Newer](:?page=" + strconv.Itoa(pg-1) + ")")
		}
		if pg < pages {
			b.WriteString(" · [Older](:?page=" + strconv.Itoa(pg+1) + ")")
		}
		b.WriteString("\n")
	}
	return b.String()
}

func renderPoll(p *poll) string {
	var b strings.Builder
	b.WriteString("# Poll " + strconv.Itoa(p.id) + "\n\n")
	b.WriteString("**" + sanitize.InlineText(p.question) + "**\n\n")
	b.WriteString("Opened by [" + p.author.String() + "](/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0:u/" + p.author.String() + ") at block " + strconv.FormatInt(p.height, 10) + "\n\n")
	b.WriteString("| # | Option | Votes |\n|---|---|---|\n")
	for i, o := range p.options {
		b.WriteString("| " + strconv.Itoa(i) + " | " + sanitize.TableCell(o) + " | " + strconv.FormatInt(p.votes[i], 10) + " |\n")
	}
	b.WriteString("\n[All polls](:)\n")
	return b.String()
}

func notFound() string { return "# Not found\n\n[All polls](:)\n" }

func getPoll(id int) *poll {
	if id < 1 || id >= nextID {
		return nil
	}
	v := polls.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*poll)
}

// key zero-pads ids so the tree iterates in creation order.
func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func pageParam(query string) int {
	for _, kv := range strings.Split(query, "&") {
		if v, ok := strings.CutPrefix(kv, "page="); ok {
			if n, err := strconv.Atoi(v); err == nil && n > 0 && n < 1_000_000 {
				return n
			}
		}
	}
	return 1
}

// validText accepts 1..max printable ASCII characters.
func validText(s string, max int) bool {
	if len(s) == 0 || len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < 0x20 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

// Package lounge is a VIP guestbook: a pure Barkeep consumer. Only patrons
// with at least the Regular tier may sign; it never attests anyone.
package lounge

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/renown/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0"
)

const (
	MinScore   = renown.RegularMin // Regular tier
	MaxMsgLen  = 100
	MaxEntries = 20 // ring buffer: oldest entry is overwritten
)

type entry struct {
	who    address
	tier   string
	msg    string
	height int64
}

var (
	book  []entry
	next  int // ring position of the next write once full
	total int // signatures ever written
)

// Sign adds a line to the guestbook. It panics for Strangers and for
// messages that are empty, too long or not printable ASCII.
func Sign(cur realm, msg string) {
	who := cur.Previous().Address()
	if !barkeep.HasMinScore(who, MinScore) {
		panic("lounge: Regulars only, come back with a Barkeep score of " + strconv.FormatInt(MinScore, 10))
	}
	msg = strings.TrimSpace(msg)
	if len(msg) == 0 || len(msg) > MaxMsgLen {
		panic("lounge: message must be 1-100 characters")
	}
	for i := 0; i < len(msg); i++ {
		if msg[i] < 0x20 || msg[i] > 0x7e {
			panic("lounge: message must be printable ASCII")
		}
	}
	add(entry{who: who, tier: barkeep.TierOf(who), msg: msg, height: runtime.ChainHeight()})
}

// add writes e into the ring buffer.
func add(e entry) {
	if len(book) < MaxEntries {
		book = append(book, e)
	} else {
		book[next] = e
		next = (next + 1) % MaxEntries
	}
	total++
}

// Signatures returns how many times the book was signed.
func Signatures() int { return total }

// Render lists the kept entries, newest first.
func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# The Lounge\n\nVIP guestbook for Regulars and above, gated by [Barkeep](/r/g1dmwvymew9ku97tp30xka70w4tnn8cydh2tct9p/barkeep/v0).\n\n")
	if len(book) == 0 {
		return b.String() + "_Nobody has signed yet._\n"
	}
	b.WriteString("| Block | Patron | Tier | Message |\n|---|---|---|---|\n")
	for i := 0; i < len(book); i++ {
		e := book[(next-1-i+2*len(book))%len(book)]
		b.WriteString("| " + strconv.FormatInt(e.height, 10) + " | " + e.who.String() + " | " + e.tier + " | " + sanitize.TableCell(e.msg) + " |\n")
	}
	return b.String()
}

// Package questboard is an escrowed bounty board for Gno.land.
//
// Anyone can post a quest (a task) and lock ugnot as its reward. Anyone else
// can add to the reward, and hunters submit proof of work (a link and a note).
// The poster, or an optional arbiter named at creation, pays the full escrow
// to one hunter with Award. If the quest is cancelled, or if nobody decides
// within GracePeriod after the deadline, every contributor gets back exactly
// what they put in.
//
// Every address gets a public track record: how much it has paid out, how
// often it cancelled after work was submitted, how often it ghosted hunters,
// and how much it has earned as a hunter. That is the trust layer: hunters can
// see whether a poster actually pays before they start working.
package questboard

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	Denom             = "ugnot"
	MinReward   int64 = 100_000 // 0.1 GNOT
	MinTopUp    int64 = 10_000  // 0.01 GNOT
	MinDays           = 1
	MaxDays           = 90
	GracePeriod       = 7 * 24 * time.Hour

	MaxTitleLen    = 80
	MaxBodyLen     = 4000
	MaxLinkLen     = 300
	MaxNoteLen     = 500
	MaxReasonLen   = 200
	MaxSubmissions = 50
	MaxContribs    = 32
	maxRecent      = 20
)

var (
	nextID   seqid.ID
	quests   avl.Tree // seqid binary -> *Quest
	open     avl.Tree // seqid binary -> *Quest, open quests only
	closed   []int    // latest closed quest ids (bounded)
	profiles avl.Tree // address string -> *Profile

	openCount int
	escrowed  int64 // ugnot currently locked in open quests
	paidOut   int64 // ugnot paid to hunters, all time
	refunded  int64 // ugnot refunded to contributors, all time
	completed int   // quests awarded, all time
)

// PostQuest creates a quest and locks the ugnot sent with the transaction as
// its reward. days is how long hunters have to submit (1-90). arbiter is
// optional (leave empty): if set, that address can also award, reject or
// cancel, which lets a neutral party settle the quest.
//
//	gnokey maketx call -pkgpath <this realm> -func PostQuest \
//	  -args "Fix typo in README" -args "details..." -args 7 -args "" \
//	  -send 1000000ugnot ...
func PostQuest(cur realm, title, body string, days int, arbiter string) int {
	poster := cur.Previous().Address()
	amount := mustReceive(cur, MinReward)

	title = strings.TrimSpace(title)
	body = strings.TrimSpace(body)
	if title == "" {
		panic("title is required")
	}
	if len(title) > MaxTitleLen {
		panic("title too long (max " + strconv.Itoa(MaxTitleLen) + " bytes)")
	}
	if len(body) > MaxBodyLen {
		panic("body too long (max " + strconv.Itoa(MaxBodyLen) + " bytes)")
	}
	if days < MinDays || days > MaxDays {
		panic("days must be between " + strconv.Itoa(MinDays) + " and " + strconv.Itoa(MaxDays))
	}
	var arb address
	arbiter = strings.TrimSpace(arbiter)
	if arbiter != "" {
		arb = address(arbiter)
		if !arb.IsValid() {
			panic("invalid arbiter address")
		}
		if arb == poster {
			panic("arbiter must be someone other than the poster")
		}
	}

	now := time.Now()
	id := int(nextID.Next())
	q := &Quest{
		ID:        id,
		Poster:    poster,
		Arbiter:   arb,
		Title:     title,
		Body:      body,
		CreatedAt: now,
		Deadline:  now.Add(time.Duration(days) * 24 * time.Hour),
		Reward:    amount,
		Contribs:  []Contribution{{From: poster, Amount: amount}},
		Status:    StatusOpen,
	}
	quests.Set(key(id), q)
	open.Set(key(id), q)
	openCount++
	escrowed += amount

	p := profileOf(poster)
	p.Posted++
	p.Recent = append(p.Recent, id)
	if len(p.Recent) > maxRecent {
		p.Recent = p.Recent[len(p.Recent)-maxRecent:]
	}

	chain.Emit("QuestPosted",
		"id", strconv.Itoa(id),
		"poster", poster.String(),
		"reward", strconv.FormatInt(amount, 10),
		"deadline", q.Deadline.UTC().Format(time.RFC3339),
	)
	return id
}

// Fund adds the ugnot sent with the transaction to an open quest's reward.
// If the quest is later cancelled or expires, the funder is refunded.
func Fund(cur realm, id int) {
	funder := cur.Previous().Address()
	amount := mustReceive(cur, MinTopUp)
	q := mustOpen(id)
	if q.pastDeadline(time.Now()) {
		panic("quest deadline has passed")
	}

	found := false
	for i := range q.Contribs {
		if q.Contribs[i].From == funder {
			q.Contribs[i].Amount += amount
			found = true
			break
		}
	}
	if !found {
		if len(q.Contribs) >= MaxContribs {
			panic("too many contributors on this quest")
		}
		q.Contribs = append(q.Contribs, Contribution{From: funder, Amount: amount})
	}
	q.Reward += amount
	escrowed += amount
	if funder != q.Poster {
		profileOf(funder).Funded += amount
	}

	chain.Emit("QuestFunded",
		"id", strconv.Itoa(id),
		"funder", funder.String(),
		"amount", strconv.FormatInt(amount, 10),
		"reward", strconv.FormatInt(q.Reward, 10),
	)
}

// Submit records (or updates) the caller's proof of work for a quest.
// link must be an http(s) URL, e.g. a merge request, commit or demo.
func Submit(cur realm, id int, link, note string) {
	hunter := cur.Previous().Address()
	q := mustOpen(id)
	if q.pastDeadline(time.Now()) {
		panic("quest deadline has passed")
	}
	if q.isManager(hunter) {
		panic("the poster or arbiter cannot submit to their own quest")
	}
	link = strings.TrimSpace(link)
	note = strings.TrimSpace(note)
	if len(link) > MaxLinkLen {
		panic("link too long (max " + strconv.Itoa(MaxLinkLen) + " bytes)")
	}
	if !strings.HasPrefix(link, "https://") && !strings.HasPrefix(link, "http://") {
		panic("link must start with https:// or http://")
	}
	if sanitize.URL(link) == "" {
		panic("invalid link")
	}
	if len(note) > MaxNoteLen {
		panic("note too long (max " + strconv.Itoa(MaxNoteLen) + " bytes)")
	}

	now := time.Now()
	if s := q.findSub(hunter); s != nil {
		s.Link, s.Note, s.At = link, note, now
		s.Rejected, s.Reason = false, ""
	} else {
		if len(q.Subs) >= MaxSubmissions {
			panic("this quest has reached its submission limit")
		}
		q.Subs = append(q.Subs, &Submission{Hunter: hunter, Link: link, Note: note, At: now})
		profileOf(hunter).Submitted++
	}

	chain.Emit("QuestSubmitted", "id", strconv.Itoa(id), "hunter", hunter.String())
}

// Reject marks a hunter's submission as not accepted, with a short reason.
// The hunter may resubmit before the deadline. Poster or arbiter only.
func Reject(cur realm, id int, hunter string, reason string) {
	caller := cur.Previous().Address()
	q := mustOpen(id)
	if !q.isManager(caller) {
		panic("only the poster or arbiter can reject submissions")
	}
	reason = strings.TrimSpace(reason)
	if len(reason) > MaxReasonLen {
		panic("reason too long (max " + strconv.Itoa(MaxReasonLen) + " bytes)")
	}
	s := q.findSub(address(strings.TrimSpace(hunter)))
	if s == nil {
		panic("no submission from that address")
	}
	s.Rejected, s.Reason = true, reason

	chain.Emit("QuestRejected", "id", strconv.Itoa(id), "hunter", s.Hunter.String())
}

// Award pays the whole escrow to a hunter who submitted. Poster or arbiter
// only. Allowed any time while the quest is open, including after the
// deadline, until someone calls Expire.
func Award(cur realm, id int, hunter string) {
	caller := cur.Previous().Address()
	q := mustOpen(id)
	if !q.isManager(caller) {
		panic("only the poster or arbiter can award a quest")
	}
	s := q.findSub(address(strings.TrimSpace(hunter)))
	if s == nil {
		panic("no submission from that address")
	}
	if s.Rejected {
		panic("that submission was rejected")
	}

	amount := q.Reward
	q.Status = StatusAwarded
	q.Winner = s.Hunter
	q.ClosedAt = time.Now()
	markClosed(q)
	escrowed -= amount
	paidOut += amount
	completed++

	pp := profileOf(q.Poster)
	pp.Completed++
	pp.Paid += amount
	hp := profileOf(s.Hunter)
	hp.Won++
	hp.Earned += amount

	send(cur, s.Hunter, amount)

	chain.Emit("QuestAwarded",
		"id", strconv.Itoa(id),
		"hunter", s.Hunter.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
}

// Cancel closes a quest and refunds every contributor. The poster can cancel
// at any time; if work had already been submitted, that is recorded on the
// poster's public profile. The arbiter can also cancel.
func Cancel(cur realm, id int) {
	caller := cur.Previous().Address()
	q := mustOpen(id)
	if !q.isManager(caller) {
		panic("only the poster or arbiter can cancel a quest")
	}
	if q.activeSubs() > 0 && caller == q.Poster {
		profileOf(q.Poster).Cancelled++
	}
	closeAndRefund(cur, q, StatusCancelled)
	chain.Emit("QuestCancelled", "id", strconv.Itoa(id), "by", caller.String())
}

// Expire can be called by anyone once GracePeriod has passed after the
// deadline without an award. It refunds every contributor. If hunters were
// left waiting, the poster's profile records it as ghosted.
func Expire(cur realm, id int) {
	q := mustOpen(id)
	if !q.expirable(time.Now()) {
		panic("quest can only expire " + GracePeriod.String() + " after its deadline")
	}
	if q.activeSubs() > 0 {
		profileOf(q.Poster).Ghosted++
	}
	closeAndRefund(cur, q, StatusExpired)
	chain.Emit("QuestExpired", "id", strconv.Itoa(id))
}

// ---- read-only helpers for other realms and clients ----

// QuestCount returns how many quests were ever posted.
func QuestCount() int { return quests.Size() }

// RewardOf returns the current reward (ugnot) and status of a quest.
func RewardOf(id int) (int64, string) {
	q := mustGet(id)
	return q.Reward, q.Status.String()
}

// Stats returns board-wide totals: open quests, ugnot in escrow, ugnot paid
// to hunters, quests completed.
func Stats() (int, int64, int64, int) {
	return openCount, escrowed, paidOut, completed
}

// ---- internals ----

func closeAndRefund(cur realm, q *Quest, st Status) {
	q.Status = st
	q.ClosedAt = time.Now()
	markClosed(q)
	escrowed -= q.Reward
	refunded += q.Reward
	for _, c := range q.Contribs {
		if c.Amount > 0 {
			send(cur, c.From, c.Amount)
		}
	}
}

func markClosed(q *Quest) {
	open.Remove(key(q.ID))
	openCount--
	closed = append(closed, q.ID)
	if len(closed) > maxRecent {
		closed = closed[len(closed)-maxRecent:]
	}
}

// mustReceive checks that the transaction sent at least min ugnot to this
// realm, and nothing else. Only direct user calls are accepted: OriginSend
// describes coins that actually landed here only for a pure EOA call.
func mustReceive(cur realm, min int64) int64 {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls (maketx call) can send funds")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("send exactly one coin type: " + Denom)
	}
	amount := sent[0].Amount
	if amount < min {
		panic("send at least " + strconv.FormatInt(min, 10) + Denom)
	}
	return amount
}

func send(cur realm, to address, amount int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin(Denom, amount)})
}

func key(id int) string { return seqid.ID(id).Binary() }

func getQuest(id int) *Quest {
	if id <= 0 {
		return nil
	}
	v := quests.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*Quest)
}

func mustGet(id int) *Quest {
	q := getQuest(id)
	if q == nil {
		panic("quest not found")
	}
	return q
}

func mustOpen(id int) *Quest {
	q := mustGet(id)
	if q.Status != StatusOpen {
		panic("quest is " + q.Status.String())
	}
	return q
}

func profileOf(addr address) *Profile {
	if v := profiles.Get(addr.String()); v != nil {
		return v.(*Profile)
	}
	p := &Profile{}
	profiles.Set(addr.String(), p)
	return p
}

func peekProfile(addr address) *Profile {
	v := profiles.Get(addr.String())
	if v == nil {
		return nil
	}
	return v.(*Profile)
}

func avlTree() avl.Tree { return avl.Tree{} }

package questboard

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render serves the board in gnoweb:
//
//	""            home: totals, open quests, recently closed
//	"quest/<id>"  one quest with its submissions and action links
//	"u/<addr>"    an address's public track record
func Render(path string) string {
	path = strings.Trim(path, "/")
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "quest/"):
		id, err := strconv.Atoi(strings.TrimPrefix(path, "quest/"))
		if err != nil {
			return "# 404\n\nBad quest id. [Back to the board](" + homeURL() + ")"
		}
		return renderQuest(id)
	case strings.HasPrefix(path, "u/"):
		return renderProfile(address(strings.TrimPrefix(path, "u/")))
	}
	return "# 404\n\n[Back to the board](" + homeURL() + ")"
}

const maxHomeRows = 30

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Quest Board\n\n")
	b.WriteString("Post a task, lock GNOT as the reward, and pay whoever delivers. ")
	b.WriteString("The reward sits in this realm's escrow until the poster awards it or it is refunded, ")
	b.WriteString("and every address builds a public record of what it paid and what it earned.\n\n")
	b.WriteString(ufmt.Sprintf("**%d** open quests · **%s** in escrow · **%s** paid to hunters · **%d** quests completed\n\n",
		openCount, gnot(escrowed), gnot(paidOut), completed))
	b.WriteString("[**+ Post a quest**](" + txlink.NewLink("PostQuest").AddArgs("days", "7").SetSend("1000000ugnot").URL() + ")\n\n")

	b.WriteString("## Open quests\n\n")
	if open.Size() == 0 {
		b.WriteString("_No open quests yet. Be the first to post one._\n\n")
	} else {
		b.WriteString("| # | Quest | Reward | Due (UTC) | Submissions |\n|---|---|---|---|---|\n")
		shown := 0
		open.ReverseIterate("", "", func(_ string, v any) bool {
			if shown >= maxHomeRows {
				return true
			}
			shown++
			q := v.(*Quest)
			b.WriteString(ufmt.Sprintf("| %d | [%s](%s) | %s | %s | %d |\n",
				q.ID, sanitize.TableCell(q.Title), questURL(q.ID), gnot(q.Reward), dueLabel(q), len(q.Subs)))
			return false
		})
		b.WriteString("\n")
		if open.Size() > maxHomeRows {
			b.WriteString(ufmt.Sprintf("_Showing the newest %d of %d open quests._\n\n", maxHomeRows, open.Size()))
		}
	}

	if len(closed) > 0 {
		b.WriteString("## Recently closed\n\n")
		for i := len(closed) - 1; i >= 0; i-- {
			q := getQuest(closed[i])
			if q == nil {
				continue
			}
			line := ufmt.Sprintf("- [#%d %s](%s): %s, %s", q.ID, sanitize.InlineText(q.Title), questURL(q.ID), q.Status.String(), gnot(q.Reward))
			if q.Status == StatusAwarded {
				line += " to " + addrLink(q.Winner)
			}
			b.WriteString(line + "\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## How it works\n\n")
	b.WriteString("1. **Post** a quest with `PostQuest` and send the reward (at least " + gnot(MinReward) + "). Optionally name an arbiter.\n")
	b.WriteString("2. **Fund**: anyone can add to the reward with `Fund`. Funders are refunded if the quest does not pay out.\n")
	b.WriteString("3. **Submit**: hunters post a link to their work with `Submit` before the deadline.\n")
	b.WriteString("4. **Award**: the poster (or arbiter) pays the whole escrow to one hunter with `Award`, or turns a submission down with `Reject`.\n")
	b.WriteString("5. **Refund**: `Cancel` refunds everyone. If nobody decides within " + days(GracePeriod) + " after the deadline, anyone can call `Expire` to refund.\n\n")
	b.WriteString("Cancelling after work was submitted, or letting a quest expire with hunters waiting, shows up on the poster's profile at `:u/<address>`.\n")
	return b.String()
}

func renderQuest(id int) string {
	q := getQuest(id)
	if q == nil {
		return "# 404\n\nQuest not found. [Back to the board](" + homeURL() + ")"
	}
	now := time.Now()
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# #%d %s\n\n", q.ID, sanitize.InlineText(q.Title)))
	b.WriteString("[← Board](" + homeURL() + ")\n\n")
	b.WriteString(ufmt.Sprintf("- **Status:** %s\n", statusLabel(q, now)))
	b.WriteString(ufmt.Sprintf("- **Reward:** %s\n", gnot(q.Reward)))
	b.WriteString(ufmt.Sprintf("- **Poster:** %s\n", addrLink(q.Poster)+posterSummary(q.Poster)))
	if q.Arbiter != "" {
		b.WriteString(ufmt.Sprintf("- **Arbiter:** %s\n", addrLink(q.Arbiter)))
	}
	b.WriteString(ufmt.Sprintf("- **Posted:** %s\n", fmtTime(q.CreatedAt)))
	b.WriteString(ufmt.Sprintf("- **Deadline:** %s\n", fmtTime(q.Deadline)))
	if q.Status == StatusAwarded {
		b.WriteString(ufmt.Sprintf("- **Winner:** %s\n", addrLink(q.Winner)))
	}
	b.WriteString("\n")

	if q.Body != "" {
		b.WriteString("## Details\n")
		b.WriteString(sanitize.Block(q.Body))
		b.WriteString("\n")
	}

	if q.Status == StatusOpen {
		ids := strconv.Itoa(q.ID)
		b.WriteString("## Actions\n\n")
		if !q.pastDeadline(now) {
			b.WriteString("- [Submit your work](" + txlink.NewLink("Submit").AddArgs("id", ids).URL() + ")\n")
			b.WriteString("- [Add to the reward](" + txlink.NewLink("Fund").AddArgs("id", ids).SetSend("100000ugnot").URL() + ")\n")
		}
		b.WriteString("- Poster / arbiter: [Award](" + txlink.NewLink("Award").AddArgs("id", ids).URL() + ") · [Reject a submission](" +
			txlink.NewLink("Reject").AddArgs("id", ids).URL() + ") · [Cancel and refund](" + txlink.NewLink("Cancel").AddArgs("id", ids).URL() + ")\n")
		if q.expirable(now) {
			b.WriteString("- Anyone: [Expire and refund](" + txlink.NewLink("Expire").AddArgs("id", ids).URL() + ")\n")
		}
		b.WriteString("\n")
	}

	b.WriteString(ufmt.Sprintf("## Submissions (%d)\n\n", len(q.Subs)))
	if len(q.Subs) == 0 {
		b.WriteString("_None yet._\n\n")
	} else {
		b.WriteString("| Hunter | Work | Note | When (UTC) | State |\n|---|---|---|---|---|\n")
		for _, s := range q.Subs {
			state := "pending"
			if q.Status == StatusAwarded && s.Hunter == q.Winner {
				state = "**winner**"
			} else if s.Rejected {
				state = "rejected"
				if s.Reason != "" {
					state += ": " + sanitize.TableCell(s.Reason)
				}
			} else if q.Status != StatusOpen {
				state = "-"
			}
			work := "-"
			if u := sanitize.URL(s.Link); u != "" {
				work = "[link](" + u + ")"
			}
			b.WriteString(ufmt.Sprintf("| %s | %s | %s | %s | %s |\n",
				addrLink(s.Hunter), work, sanitize.TableCell(s.Note), fmtTime(s.At), state))
		}
		b.WriteString("\n")
	}

	b.WriteString(ufmt.Sprintf("## Funders (%d)\n\n", len(q.Contribs)))
	for _, c := range q.Contribs {
		b.WriteString(ufmt.Sprintf("- %s: %s\n", addrLink(c.From), gnot(c.Amount)))
	}
	return b.String()
}

func renderProfile(addr address) string {
	if !addr.IsValid() {
		return "# 404\n\nInvalid address. [Back to the board](" + homeURL() + ")"
	}
	var b strings.Builder
	b.WriteString("# Track record\n\n")
	b.WriteString("`" + addr.String() + "`\n\n[← Board](" + homeURL() + ")\n\n")
	p := peekProfile(addr)
	if p == nil {
		b.WriteString("_No activity on this board yet._\n")
		return b.String()
	}
	b.WriteString("## As a poster\n\n")
	b.WriteString(ufmt.Sprintf("- Quests posted: **%d**\n", p.Posted))
	b.WriteString(ufmt.Sprintf("- Paid out: **%d** quests, **%s**\n", p.Completed, gnot(p.Paid)))
	b.WriteString(ufmt.Sprintf("- Cancelled after work was submitted: **%d**\n", p.Cancelled))
	b.WriteString(ufmt.Sprintf("- Expired with hunters waiting (ghosted): **%d**\n", p.Ghosted))
	b.WriteString(ufmt.Sprintf("- Added to others' rewards: **%s**\n\n", gnot(p.Funded)))
	b.WriteString("## As a hunter\n\n")
	b.WriteString(ufmt.Sprintf("- Submissions: **%d**\n", p.Submitted))
	b.WriteString(ufmt.Sprintf("- Quests won: **%d**, earned **%s**\n\n", p.Won, gnot(p.Earned)))
	if len(p.Recent) > 0 {
		b.WriteString("## Recent quests posted\n\n")
		for i := len(p.Recent) - 1; i >= 0; i-- {
			q := getQuest(p.Recent[i])
			if q == nil {
				continue
			}
			b.WriteString(ufmt.Sprintf("- [#%d %s](%s): %s, %s\n", q.ID, sanitize.InlineText(q.Title), questURL(q.ID), q.Status.String(), gnot(q.Reward)))
		}
	}
	return b.String()
}

// ---- formatting helpers ----

// homeURL is this realm's gnoweb path, e.g. /r/<addr>/questboard.
func homeURL() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func questURL(id int) string { return homeURL() + ":quest/" + strconv.Itoa(id) }
func addrLink(a address) string {
	s := a.String()
	short := s
	if len(s) > 14 {
		short = s[:8] + "…" + s[len(s)-4:]
	}
	return "[" + short + "](" + homeURL() + ":u/" + s + ")"
}

func posterSummary(a address) string {
	p := peekProfile(a)
	if p == nil {
		return ""
	}
	return ufmt.Sprintf(" (paid %d of %d quests, %s total)", p.Completed, p.Posted, gnot(p.Paid))
}

func statusLabel(q *Quest, now time.Time) string {
	if q.Status != StatusOpen {
		return q.Status.String() + " on " + fmtTime(q.ClosedAt)
	}
	if !q.pastDeadline(now) {
		return "open, " + remaining(q.Deadline.Sub(now)) + " left to submit"
	}
	if q.expirable(now) {
		return "awaiting decision (grace period over: anyone can Expire)"
	}
	return "awaiting decision, " + remaining(q.Deadline.Add(GracePeriod).Sub(now)) + " until refundable"
}

func dueLabel(q *Quest) string {
	now := time.Now()
	if q.pastDeadline(now) {
		return "closed for submissions"
	}
	return q.Deadline.UTC().Format("2006-01-02") + " (" + remaining(q.Deadline.Sub(now)) + ")"
}

func remaining(d time.Duration) string {
	if d <= 0 {
		return "0h"
	}
	h := int(d / time.Hour)
	if h >= 48 {
		return strconv.Itoa(h/24) + "d"
	}
	if h >= 1 {
		return strconv.Itoa(h) + "h"
	}
	return strconv.Itoa(int(d/time.Minute)) + "m"
}

func days(d time.Duration) string { return strconv.Itoa(int(d/(24*time.Hour))) + " days" }

func fmtTime(t time.Time) string { return t.UTC().Format("2006-01-02 15:04") }

// gnot formats an ugnot amount as GNOT, e.g. 1500000 -> "1.5 GNOT".
func gnot(u int64) string {
	whole := u / 1_000_000
	frac := u % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fs := strconv.FormatInt(frac+1_000_000, 10)[1:]
	fs = strings.TrimRight(fs, "0")
	return strconv.FormatInt(whole, 10) + "." + fs + " GNOT"
}

package questboard

import (
	"time"
)

// Status is the lifecycle state of a quest.
type Status int

const (
	StatusOpen      Status = iota // accepting submissions / funds
	StatusAwarded                 // escrow paid to a hunter
	StatusCancelled               // escrow refunded by poster or arbiter
	StatusExpired                 // nobody decided in time; escrow refunded
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusAwarded:
		return "awarded"
	case StatusCancelled:
		return "cancelled"
	case StatusExpired:
		return "expired"
	}
	return "unknown"
}

// Submission is a hunter's claim that the quest is done.
type Submission struct {
	Hunter   address
	Link     string
	Note     string
	At       time.Time
	Rejected bool
	Reason   string
}

// Contribution is the total ugnot one address locked in a quest.
type Contribution struct {
	From   address
	Amount int64
}

// Quest is one escrowed bounty.
type Quest struct {
	ID        int
	Poster    address
	Arbiter   address // optional third party allowed to award, reject or cancel
	Title     string
	Body      string
	CreatedAt time.Time
	Deadline  time.Time
	Reward    int64 // ugnot currently held in escrow (or paid out once closed)
	Contribs  []Contribution
	Subs      []*Submission
	Status    Status
	Winner    address
	ClosedAt  time.Time
}

// Profile is the public, on-chain track record of an address.
type Profile struct {
	Posted    int   // quests posted
	Completed int   // quests this address posted and paid out
	Paid      int64 // ugnot paid to hunters from quests this address posted
	Cancelled int   // quests cancelled after someone had submitted work
	Ghosted   int   // quests that expired with pending submissions (poster never decided)
	Submitted int   // submissions made as a hunter
	Won       int   // quests won as a hunter
	Earned    int64 // ugnot earned as a hunter
	Funded    int64 // ugnot contributed to other people's quests
	Recent    []int // latest quest ids this address posted (bounded)
}

func (q *Quest) isManager(addr address) bool {
	return addr == q.Poster || (q.Arbiter != "" && addr == q.Arbiter)
}

func (q *Quest) findSub(hunter address) *Submission {
	for _, s := range q.Subs {
		if s.Hunter == hunter {
			return s
		}
	}
	return nil
}

func (q *Quest) activeSubs() int {
	n := 0
	for _, s := range q.Subs {
		if !s.Rejected {
			n++
		}
	}
	return n
}

func (q *Quest) pastDeadline(now time.Time) bool {
	return now.After(q.Deadline)
}

func (q *Quest) expirable(now time.Time) bool {
	return now.After(q.Deadline.Add(GracePeriod))
}

// Package quests is the Tavern Quests realm: an on-chain quest board
// where anyone can post a task with GNOT escrowed in the realm, another
// user claims and delivers it, and the poster releases the escrow on
// approval — a working bounty market that lives entirely in one realm
// and renders its board in gnoweb.
//
// All lifecycle rules (who may act, which transitions are legal) live in
// the pure package gno.land/p/nym-tavern777/escrow; this realm only stores the
// records, verifies the payment attached to a new quest, and moves coins
// when the state machine reaches a payout or refund transition.
package quests

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nym-tavern777/escrow"
)

// denom is the only coin this board escrows: GNOT's base denom.
const denom = "ugnot"

var (
	quests  []*escrow.Quest
	counter int64
)

// PostQuest creates a quest, escrowing the ugnot sent with the call as
// the reward. The call must carry exactly one coin type (ugnot); the
// realm holds it until ApproveQuest pays the claimant or CancelQuest
// refunds the poster.
//
// Only a direct user call (maketx call) is accepted: OriginSend describes
// a real payment to this realm only when the caller is a pure EOA. An
// intermediate realm could otherwise consume the send envelope elsewhere
// and have this realm record a phantom escrow against its own balance.
func PostQuest(cur realm, title string, description string) int64 {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}
	poster := cur.Previous().Address()

	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("send exactly " + denom + " as the quest reward")
	}
	reward := sent[0].Amount

	if err := escrow.ValidateNew(title, description, reward); err != nil {
		panic(err.Error())
	}

	counter++
	q := &escrow.Quest{
		ID:          counter,
		Poster:      poster,
		Title:       title,
		Description: description,
		Reward:      reward,
		Status:      escrow.Open,
	}
	quests = append(quests, q)
	return q.ID
}

// ClaimQuest claims an open quest for the caller. One claimant per quest;
// the poster cannot claim their own quest.
func ClaimQuest(cur realm, id int64) {
	caller := cur.Previous().Address()
	q := mustGet(id)
	if err := escrow.Claim(q, caller); err != nil {
		panic(err.Error())
	}
}

// SubmitWork records the claimant's delivery note (a link or reference
// to the delivered work) and marks the quest submitted.
func SubmitWork(cur realm, id int64, note string) {
	caller := cur.Previous().Address()
	q := mustGet(id)
	if err := escrow.Submit(q, caller, note); err != nil {
		panic(err.Error())
	}
}

// ApproveQuest releases the escrowed reward to the claimant. Poster only,
// and only after work has been submitted.
func ApproveQuest(cur realm, id int64) {
	caller := cur.Previous().Address()
	q := mustGet(id)
	if err := escrow.Approve(q, caller); err != nil {
		panic(err.Error())
	}
	pay(cur, q.Claimant, q.Reward)
}

// RejectQuest sends a submitted quest back to the claimant for another
// attempt, clearing the delivery note. Poster only.
func RejectQuest(cur realm, id int64) {
	caller := cur.Previous().Address()
	q := mustGet(id)
	if err := escrow.Reject(q, caller); err != nil {
		panic(err.Error())
	}
}

// CancelQuest closes an open (not yet claimed) quest and refunds the
// escrowed reward to the poster. Poster only.
func CancelQuest(cur realm, id int64) {
	caller := cur.Previous().Address()
	q := mustGet(id)
	if err := escrow.Cancel(q, caller); err != nil {
		panic(err.Error())
	}
	pay(cur, q.Poster, q.Reward)
}

// pay sends amt ugnot out of the realm's own balance.
func pay(cur realm, to address, amt int64) {
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{Denom: denom, Amount: amt}})
}

func mustGet(id int64) *escrow.Quest {
	if id < 1 || id > int64(len(quests)) {
		panic("unknown quest id")
	}
	return quests[id-1]
}

// Render draws the board for gnoweb: with no path, the quest list grouped
// by status with counts; with a quest id as path, that quest's detail.
func Render(path string) string {
	if path != "" {
		id, err := strconv.ParseInt(path, 10, 64)
		if err != nil || id < 1 || id > int64(len(quests)) {
			return "# Tavern Quests\n\nUnknown quest: " + sanitizeInline(path) + "\n"
		}
		return renderQuest(quests[id-1])
	}

	var open, claimed, submitted, completed, cancelled int
	for _, q := range quests {
		switch q.Status {
		case escrow.Open:
			open++
		case escrow.Claimed:
			claimed++
		case escrow.Submitted:
			submitted++
		case escrow.Completed:
			completed++
		case escrow.Cancelled:
			cancelled++
		}
	}

	var sb strings.Builder
	sb.WriteString("# Tavern Quests\n\n")
	sb.WriteString("Post a task with GNOT in escrow, claim someone else's, get paid on delivery.\n\n")
	sb.WriteString("**" + strconv.Itoa(len(quests)) + " quests** — " +
		strconv.Itoa(open) + " open · " +
		strconv.Itoa(claimed) + " claimed · " +
		strconv.Itoa(submitted) + " submitted · " +
		strconv.Itoa(completed) + " completed · " +
		strconv.Itoa(cancelled) + " cancelled\n\n")

	if len(quests) == 0 {
		sb.WriteString("No quests yet. Post the first one.\n")
		return sb.String()
	}

	sb.WriteString("## Quests\n\n")
	// Newest first.
	for i := len(quests) - 1; i >= 0; i-- {
		q := quests[i]
		id := strconv.FormatInt(q.ID, 10)
		sb.WriteString("- [" + q.Status.String() + " #" + id + "](" + id + ") — " +
			sanitizeInline(q.Title) + " — reward **" + formatReward(q.Reward) +
			"** — poster " + q.Poster.String() + "\n")
	}
	return sb.String()
}

func renderQuest(q *escrow.Quest) string {
	var sb strings.Builder
	sb.WriteString("# Quest #" + strconv.FormatInt(q.ID, 10) + " — " + sanitizeInline(q.Title) + "\n\n")
	sb.WriteString("- Status: **" + q.Status.String() + "**\n")
	sb.WriteString("- Reward: **" + formatReward(q.Reward) + "** (escrowed in this realm)\n")
	sb.WriteString("- Poster: " + q.Poster.String() + "\n")
	if q.Claimant != "" {
		sb.WriteString("- Claimant: " + q.Claimant.String() + "\n")
	}
	if q.Description != "" {
		sb.WriteString("\n## Description\n\n")
		sb.WriteString(sanitizeBlock(q.Description))
		sb.WriteString("\n")
	}
	if q.Submission != "" {
		sb.WriteString("\n## Submission\n\n")
		sb.WriteString(sanitizeBlock(q.Submission))
		sb.WriteString("\n")
	}
	sb.WriteString("\n[← Back to the board](./)\n")
	return sb.String()
}

// formatReward renders a ugnot amount as a decimal GNOT string.
func formatReward(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fracStr := strconv.FormatInt(frac, 10)
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	fracStr = strings.TrimRight(fracStr, "0")
	return strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

// sanitizeInline makes user-supplied text safe to embed in a markdown
// line: it escapes markdown control characters and flattens newlines, so
// a crafted title cannot break the board layout or inject headings/links.
func sanitizeInline(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"<", "&lt;",
		">", "&gt;",
		"|", "\\|",
		"\r", " ",
		"\n", " ",
	)
	return r.Replace(s)
}

// sanitizeBlock is sanitizeInline for multi-line text: newlines are kept
// (they are paragraph structure, not layout attacks), control characters
// are still escaped.
func sanitizeBlock(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"<", "&lt;",
		">", "&gt;",
	)
	return r.Replace(s)
}

