package questboard

import (
	"strconv"

	"gno.land/p/nt/svg/v0"
)

// Rank is a hunter's title, earned by the number of quests won.
type Rank struct {
	Name    string
	MinWins int
	Color   string // shield fill
	Trim    string // border and ribbon
}

var ranks = []Rank{
	{"Wanderer", 0, "#8d8d8d", "#5a5a5a"},
	{"Apprentice", 1, "#4f8a5b", "#2f5a39"},
	{"Journeyman", 3, "#3a6fb0", "#24477a"},
	{"Veteran", 10, "#8a4fb0", "#5b2f7a"},
	{"Legend", 25, "#d4a017", "#8a6508"},
}

func rankOf(wins int) Rank {
	r := ranks[0]
	for _, candidate := range ranks {
		if wins >= candidate.MinWins {
			r = candidate
		}
	}
	return r
}

// nextRank returns the rank after the current one, or a zero Rank at the top.
func nextRank(wins int) Rank {
	for _, candidate := range ranks {
		if candidate.MinWins > wins {
			return candidate
		}
	}
	return Rank{}
}

// badge draws a shield with the hunter's rank, wins and earnings as an
// inline SVG image.
func badge(r Rank, wins int, earned int64) string {
	c := svg.NewCanvas(180, 210).WithViewBox(0, 0, 180, 210)
	c.AddStyle("text", "font-family:Georgia,serif;text-anchor:middle")
	c.Append(
		svg.NewPolygon("90,6 170,34 160,130 90,200 20,130 10,34", r.Trim),
		svg.NewPolygon("90,18 158,42 150,124 90,186 30,124 22,42", r.Color),
		// a gnome hat
		svg.NewPolygon("90,40 112,96 68,96", "#c0392b"),
		svg.NewRectangle(62, 94, 56, 10, "#ecf0f1"),
		svg.NewText(90, 128, r.Name, "#ffffff"),
		svg.NewText(90, 150, strconv.Itoa(wins)+" won", "#ffffff"),
		svg.NewText(90, 170, formatGNOT(earned), "#ffffff"),
	)
	return c.Render(r.Name + " badge")
}

// Package questboard is a tavern notice board for Gno.land: anyone can pin a
// quest with a GNOT reward locked in the realm, anyone can chip in to grow the
// reward, hunters hand in their work, and the poster pays one or several
// hunters straight from escrow. If a poster disappears, anyone can expire the
// quest after a grace period and every backer gets their share back.
//
// Every state change is public and every payout is enforced by this realm, so
// the board doubles as an on-chain reputation record for hunters (quests won,
// GNOT earned) and posters (how often they actually pay).
package questboard

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"math/bits"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	denom = "ugnot"

	// MinReward is the smallest reward a quest can be pinned with (0.1 GNOT).
	MinReward int64 = 100_000
	// MinChipIn is the smallest amount accepted by Fund (0.01 GNOT).
	MinChipIn int64 = 10_000

	MinDays = 1
	MaxDays = 90

	// GracePeriod is how long a poster has after the deadline to settle
	// before anyone may call Expire and refund the backers.
	GracePeriod = 7 * 24 * time.Hour

	MaxTitleLen    = 80
	MaxDetailsLen  = 2000
	MaxProofLen    = 280
	MaxNoteLen     = 140
	MaxBackers     = 50
	MaxSubmissions = 100
)

// Status is the lifecycle state of a quest.
type Status int

const (
	StatusOpen      Status = iota
	StatusCompleted        // settled with at least one award
	StatusCancelled        // settled without any award, all funds returned
)

func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusCompleted:
		return "completed"
	case StatusCancelled:
		return "cancelled"
	}
	return "unknown"
}

// Submission is a hunter's hand-in for a quest.
type Submission struct {
	Hunter  address
	Proof   string
	At      time.Time
	Awarded int64
}

// Payout is one payout made from a quest's escrow.
type Payout struct {
	Hunter address
	Amount int64
	Note   string
	At     time.Time
}

// Quest is a pinned task with an escrowed reward.
type Quest struct {
	ID        int
	Poster    address
	Title     string
	Details   string
	CreatedAt time.Time
	Deadline  time.Time
	ClosedAt  time.Time
	Status    Status
	Expired   bool // settled through Expire rather than by the poster

	Pool     int64 // everything ever funded
	Paid     int64 // everything awarded to hunters
	Refunded int64 // everything returned to backers

	backers  []address // in order of first contribution
	contribs avl.Tree  // address -> int64
	hunters  []address // in order of first hand-in
	subs     avl.Tree  // address -> *Submission
	Awards   []Payout
}

// Remaining is the GNOT (in ugnot) still held in escrow for the quest.
func (q *Quest) Remaining() int64 {
	return q.Pool - q.Paid - q.Refunded
}

// Profile aggregates what an address has done on the board.
type Profile struct {
	// as hunter
	HandIns int
	Wins    int
	Earned  int64
	// as poster
	Posted    int
	Completed int
	Cancelled int
	Expired   int // quests the poster let expire
	PaidOut   int64
	// as backer
	Backed int64
}

var (
	quests   avl.Tree // padded id -> *Quest
	profiles avl.Tree // address -> *Profile
	lastID   int

	totalPaid    int64
	totalEscrow  int64
	paidHunters  int
	settledCount int
)

// PostQuest pins a new quest. The reward is the ugnot sent with the call and is
// held by the realm until it is awarded or refunded. It returns the quest id.
func PostQuest(cur realm, title, details string, days int) int {
	caller := mustCaller(cur)
	if !cur.Previous().IsUserCall() {
		panic(errIndirectPayment)
	}
	amount := sentUgnot()

	title = strings.TrimSpace(title)
	details = strings.TrimSpace(details)
	if title == "" {
		panic("title is required")
	}
	if len(title) > MaxTitleLen {
		panic(ufmt.Sprintf("title is too long: %d bytes, max %d", len(title), MaxTitleLen))
	}
	if len(details) > MaxDetailsLen {
		panic(ufmt.Sprintf("details are too long: %d bytes, max %d", len(details), MaxDetailsLen))
	}
	if days < MinDays || days > MaxDays {
		panic(ufmt.Sprintf("days must be between %d and %d", MinDays, MaxDays))
	}
	if amount < MinReward {
		panic(ufmt.Sprintf("send at least %s as the reward", formatGNOT(MinReward)))
	}

	lastID++
	now := time.Now()
	q := &Quest{
		ID:        lastID,
		Poster:    caller,
		Title:     title,
		Details:   details,
		CreatedAt: now,
		Deadline:  now.Add(time.Duration(days) * 24 * time.Hour),
		Status:    StatusOpen,
	}
	q.addContribution(caller, amount)
	quests.Set(questKey(q.ID), q)

	p := profileOf(caller)
	p.Posted++
	p.Backed += amount
	totalEscrow += amount

	chain.Emit("QuestPosted",
		"id", strconv.Itoa(q.ID),
		"poster", caller.String(),
		"reward", strconv.FormatInt(amount, 10),
	)
	return q.ID
}

// Fund adds the ugnot sent with the call to an open quest's reward. Anyone can
// chip in; unawarded funds are returned pro rata when the quest is settled.
func Fund(cur realm, id int) {
	caller := mustCaller(cur)
	if !cur.Previous().IsUserCall() {
		panic(errIndirectPayment)
	}
	amount := sentUgnot()
	q := mustOpen(id)

	if !time.Now().Before(q.Deadline) {
		panic("quest deadline has passed")
	}
	if amount < MinChipIn {
		panic(ufmt.Sprintf("send at least %s", formatGNOT(MinChipIn)))
	}
	if !q.contribs.Has(caller.String()) && len(q.backers) >= MaxBackers {
		panic("quest has reached the maximum number of backers")
	}

	q.addContribution(caller, amount)
	profileOf(caller).Backed += amount
	totalEscrow += amount

	chain.Emit("QuestFunded",
		"id", strconv.Itoa(id),
		"backer", caller.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
}

// Submit hands in work for a quest. Proof is a short text or a link. A hunter
// can replace their hand-in until it has been awarded.
func Submit(cur realm, id int, proof string) {
	caller := mustCaller(cur)
	q := mustOpen(id)

	if !time.Now().Before(q.Deadline) {
		panic("quest deadline has passed")
	}
	if caller == q.Poster {
		panic("posters cannot hand in work for their own quest")
	}
	proof = strings.TrimSpace(proof)
	if proof == "" {
		panic("proof is required")
	}
	if len(proof) > MaxProofLen {
		panic(ufmt.Sprintf("proof is too long: %d bytes, max %d", len(proof), MaxProofLen))
	}

	if v, ok := lookup(&q.subs, caller.String()); ok {
		s := v.(*Submission)
		if s.Awarded > 0 {
			panic("your hand-in has already been awarded")
		}
		s.Proof = proof
		s.At = time.Now()
	} else {
		if len(q.hunters) >= MaxSubmissions {
			panic("quest has reached the maximum number of hand-ins")
		}
		q.subs.Set(caller.String(), &Submission{Hunter: caller, Proof: proof, At: time.Now()})
		q.hunters = append(q.hunters, caller)
		profileOf(caller).HandIns++
	}

	chain.Emit("WorkSubmitted",
		"id", strconv.Itoa(id),
		"hunter", caller.String(),
	)
}

// Award pays amount ugnot from the quest's escrow to a hunter who handed in
// work. Only the poster can award. A quest can be split between several
// hunters; it settles automatically once the escrow is empty.
func Award(cur realm, id int, hunter address, amount int64, note string) {
	caller := mustCaller(cur)
	q := mustOpen(id)

	if caller != q.Poster {
		panic("only the poster can award this quest")
	}
	v, ok := lookup(&q.subs, hunter.String())
	if !ok {
		panic("this address has not handed in work for the quest")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > q.Remaining() {
		panic(ufmt.Sprintf("only %s left in escrow", formatGNOT(q.Remaining())))
	}
	note = strings.TrimSpace(note)
	if len(note) > MaxNoteLen {
		panic(ufmt.Sprintf("note is too long: %d bytes, max %d", len(note), MaxNoteLen))
	}

	s := v.(*Submission)
	hp := profileOf(hunter)
	if s.Awarded == 0 {
		hp.Wins++
	}
	if hp.Earned == 0 {
		paidHunters++
	}
	s.Awarded += amount
	hp.Earned += amount
	profileOf(q.Poster).PaidOut += amount

	q.Paid += amount
	q.Awards = append(q.Awards, Payout{Hunter: hunter, Amount: amount, Note: note, At: time.Now()})
	totalPaid += amount
	totalEscrow -= amount

	send(cur, hunter, amount)

	chain.Emit("QuestAwarded",
		"id", strconv.Itoa(id),
		"hunter", hunter.String(),
		"amount", strconv.FormatInt(amount, 10),
	)

	if q.Remaining() == 0 {
		settle(cur, q, false)
	}
}

// Close settles a quest early and returns whatever is left in escrow to the
// backers, pro rata. Only the poster can close. Once hunters have handed in
// work, the poster must either award someone first or wait for the deadline.
func Close(cur realm, id int) {
	caller := mustCaller(cur)
	q := mustOpen(id)

	if caller != q.Poster {
		panic("only the poster can close this quest")
	}
	if len(q.hunters) > 0 && q.Paid == 0 && time.Now().Before(q.Deadline) {
		panic("hunters have handed in work: award someone, or wait for the deadline to close")
	}
	settle(cur, q, false)
}

// Expire can be called by anyone once a quest is past its deadline plus the
// grace period without being settled. It refunds every backer pro rata, so
// funds can never be stuck because a poster went missing.
func Expire(cur realm, id int) {
	mustCaller(cur)
	q := mustOpen(id)

	if time.Now().Before(q.Deadline.Add(GracePeriod)) {
		panic("quest can only be expired " + GracePeriod.String() + " after its deadline")
	}
	settle(cur, q, true)
}

// settle refunds the escrow left in q to its backers and closes it.
func settle(cur realm, q *Quest, expired bool) {
	refundRemaining(cur, q)

	q.ClosedAt = time.Now()
	q.Expired = expired
	pp := profileOf(q.Poster)
	if q.Paid > 0 {
		q.Status = StatusCompleted
		pp.Completed++
	} else {
		q.Status = StatusCancelled
		pp.Cancelled++
	}
	if expired {
		pp.Expired++
	}
	settledCount++

	chain.Emit("QuestSettled",
		"id", strconv.Itoa(q.ID),
		"status", q.Status.String(),
		"paid", strconv.FormatInt(q.Paid, 10),
	)
}

// refundRemaining returns q's remaining escrow to its backers in proportion
// to what each contributed. Rounding dust goes to the poster.
func refundRemaining(cur realm, q *Quest) {
	left := q.Remaining()
	if left == 0 {
		return
	}
	shares := splitProRata(left, q.Pool, q.backers, &q.contribs)
	for i, b := range q.backers {
		if shares[i] > 0 {
			send(cur, b, shares[i])
		}
	}
	q.Refunded += left
	totalEscrow -= left
}

// splitProRata divides amount among backers in proportion to their
// contribution out of total. The first backer (the poster) absorbs rounding
// dust, so the shares always add up to amount exactly.
func splitProRata(amount, total int64, backers []address, contribs *avl.Tree) []int64 {
	shares := make([]int64, len(backers))
	var given int64
	for i, b := range backers {
		v, _ := lookup(contribs, b.String())
		shares[i] = mulDiv(amount, v.(int64), total)
		given += shares[i]
	}
	if len(shares) > 0 {
		shares[0] += amount - given
	}
	return shares
}

// mulDiv returns a*b/c for non-negative a, b and positive c with a*b/c
// fitting in int64, computing the product in 128 bits so it cannot overflow.
func mulDiv(a, b, c int64) int64 {
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	q, _ := bits.Div64(hi, lo, uint64(c))
	return int64(q)
}

func (q *Quest) addContribution(addr address, amount int64) {
	key := addr.String()
	prev := int64(0)
	if v, ok := lookup(&q.contribs, key); ok {
		prev = v.(int64)
	} else {
		q.backers = append(q.backers, addr)
	}
	q.contribs.Set(key, prev+amount)
	q.Pool += amount
}

// send pays amount ugnot from the realm to addr.
func send(cur realm, to address, amount int64) {
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.Coins{{denom, amount}})
}

// mustCaller returns the address of the direct caller of a crossing function.
func mustCaller(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized realm")
	}
	return cur.Previous().Address()
}

// errIndirectPayment guards every function that accepts coins. Payments are
// only accepted from a direct user call (gnokey maketx call or a wallet):
// code realms and maketx run scripts could spend the send envelope before
// reaching this realm, so OriginSend would not describe coins we received.
const errIndirectPayment = "rewards must be sent with a direct call (gnokey maketx call or a wallet)"

// sentUgnot returns the ugnot attached to the call. Callers must first check
// cur.Previous().IsUserCall().
func sentUgnot() int64 {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom {
		panic("send ugnot only")
	}
	return sent[0].Amount
}

func mustOpen(id int) *Quest {
	q := getQuest(id)
	if q == nil {
		panic("quest not found")
	}
	if q.Status != StatusOpen {
		panic("quest is " + q.Status.String())
	}
	return q
}

func getQuest(id int) *Quest {
	v, ok := lookup(&quests, questKey(id))
	if !ok {
		return nil
	}
	return v.(*Quest)
}

func profileOf(addr address) *Profile {
	if v, ok := lookup(&profiles, addr.String()); ok {
		return v.(*Profile)
	}
	p := &Profile{}
	profiles.Set(addr.String(), p)
	return p
}

// questKey zero-pads ids so the avl tree iterates them in numeric order.
func questKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

// ----------------------------------------------------------------------------
// Read-only getters for wallets, bots and other realms. They return copies of
// plain values, never pointers into realm state.

// QuestCount returns how many quests have ever been pinned.
func QuestCount() int { return lastID }

// QuestStatus returns the status, escrow left and deadline of a quest.
func QuestStatus(id int) (status string, remaining int64, deadline time.Time) {
	q := getQuest(id)
	if q == nil {
		panic("quest not found")
	}
	return q.Status.String(), q.Remaining(), q.Deadline
}

// HunterStats returns how many quests a hunter has won and what they earned.
func HunterStats(addr address) (wins int, earned int64) {
	v, ok := lookup(&profiles, addr.String())
	if !ok {
		return 0, 0
	}
	p := v.(*Profile)
	return p.Wins, p.Earned
}

// PosterStats returns how many quests a poster has pinned, completed with a
// payout, and let expire.
func PosterStats(addr address) (posted, completed, expired int) {
	v, ok := lookup(&profiles, addr.String())
	if !ok {
		return 0, 0, 0
	}
	p := v.(*Profile)
	return p.Posted, p.Completed, p.Expired
}

// Totals returns board-wide figures in ugnot.
func Totals() (escrow, paid int64, hunters int) {
	return totalEscrow, totalPaid, paidHunters
}

// lookup reads key from t, reporting whether it was present.
func lookup(t *avl.Tree, key string) (any, bool) {
	if !t.Has(key) {
		return nil, false
	}
	return t.Get(key), true
}

package questboard

import (
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	"gno.land/p/jeronimoalbi/mdform/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	listLimit      = 25 // open quests shown on the home page
	recentLimit    = 5  // settled quests shown on the home page
	leaderboardLen = 10
	scanLimit      = 500 // quests scanned per render, newest first
)

// Render serves the board to gnoweb:
//
//	""             the board: stats, how it works, open quests, leaderboard
//	"quest/<id>"   one quest with its backers, hand-ins, awards and actions
//	"u/<address>"  a hunter / poster profile with a rank badge
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	switch {
	case path == "" || path == "/":
		return renderHome()
	case len(parts) == 2 && parts[0] == "quest":
		id, err := strconv.Atoi(parts[1])
		if err != nil || getQuest(id) == nil {
			return "# Quest not found\n\n[Back to the board](" + boardURL() + ")\n"
		}
		return renderQuest(getQuest(id))
	case len(parts) == 2 && parts[0] == "u":
		addr := address(parts[1])
		if !addr.IsValid() {
			return "# Unknown adventurer\n\n[Back to the board](" + boardURL() + ")\n"
		}
		return renderProfile(addr)
	}
	return "# 404\n\n[Back to the board](" + boardURL() + ")\n"
}

func renderHome() string {
	var b strings.Builder
	now := time.Now()

	b.WriteString("# 🍺 The Quest Board\n\n")
	b.WriteString("*A notice board in the tavern: pin a quest, lock the reward on-chain, pay the gnome who gets it done.*\n\n")

	openCount := 0
	var open, settled []*Quest
	scanned := 0
	quests.ReverseIterate("", "", func(_ string, v any) bool {
		q := v.(*Quest)
		if q.Status == StatusOpen {
			openCount++
			if len(open) < listLimit {
				open = append(open, q)
			}
		} else if len(settled) < recentLimit {
			settled = append(settled, q)
		}
		scanned++
		return scanned >= scanLimit
	})

	b.WriteString("| Open quests | In escrow | Paid to hunters | Hunters paid |\n")
	b.WriteString("| :---: | :---: | :---: | :---: |\n")
	b.WriteString(ufmt.Sprintf("| %d | %s | %s | %d |\n\n", openCount, formatGNOT(totalEscrow), formatGNOT(totalPaid), paidHunters))

	b.WriteString("## How it works\n\n")
	b.WriteString("1. **Pin a quest.** Call `PostQuest` with a title, details and a deadline in days, and attach the reward. The GNOT is locked in this realm, not held by anyone.\n")
	b.WriteString("2. **Chip in.** Anyone can grow a reward with `Fund`. Unused funds go back to every backer pro rata.\n")
	b.WriteString("3. **Hand in work.** Hunters call `Submit` with a link or a short note before the deadline.\n")
	b.WriteString("4. **Get paid.** The poster calls `Award`; the coins go straight from escrow to the hunter. A reward can be split between several hunters.\n")
	b.WriteString("5. **No ghosting.** If a poster never settles, anyone can call `Expire` " + days(GracePeriod) + " after the deadline and every backer is refunded. Posters who let quests expire carry it on their profile.\n\n")

	b.WriteString("**Pin a quest:** ")
	for i, amt := range []int64{1_000_000, 5_000_000, 10_000_000} {
		if i > 0 {
			b.WriteString(" · ")
		}
		b.WriteString(ufmt.Sprintf("[%s reward](%s)", formatGNOT(amt), board().NewLink("PostQuest").AddArgs("days", "7").SetSend(ufmt.Sprintf("%dugnot", amt)).URL()))
	}
	b.WriteString("\n\n")

	b.WriteString("## Open quests\n\n")
	if len(open) == 0 {
		b.WriteString("*The board is empty. Be the first to pin a quest.*\n\n")
	} else {
		b.WriteString("| # | Quest | Reward | Hand-ins | Closes |\n")
		b.WriteString("| :--- | :--- | ---: | :---: | :--- |\n")
		for _, q := range open {
			closes := "in " + humanDuration(q.Deadline.Sub(now))
			if !now.Before(q.Deadline) {
				closes = "awaiting award"
			}
			b.WriteString(ufmt.Sprintf("| %d | [%s](%s) | %s | %d | %s |\n",
				q.ID, sanitize.TableCell(q.Title), questURL(q.ID), formatGNOT(q.Remaining()), len(q.hunters), closes))
		}
		b.WriteString("\n")
	}

	if len(settled) > 0 {
		b.WriteString("## Recently settled\n\n")
		for _, q := range settled {
			b.WriteString(ufmt.Sprintf("- [#%d %s](%s): %s, %s paid to %d hunter(s)\n",
				q.ID, sanitize.InlineText(q.Title), questURL(q.ID), q.Status.String(), formatGNOT(q.Paid), awardedHunters(q)))
		}
		b.WriteString("\n")
	}

	b.WriteString("## Top hunters\n\n")
	top := topHunters(leaderboardLen)
	if len(top) == 0 {
		b.WriteString("*No hunter has been paid yet.*\n")
	} else {
		b.WriteString("| | Hunter | Rank | Quests won | Earned |\n")
		b.WriteString("| :---: | :--- | :--- | :---: | ---: |\n")
		for i, h := range top {
			b.WriteString(ufmt.Sprintf("| %d | %s | %s | %d | %s |\n",
				i+1, userLink(h.addr), rankOf(h.p.Wins).Name, h.p.Wins, formatGNOT(h.p.Earned)))
		}
	}
	return b.String()
}

func renderQuest(q *Quest) string {
	var b strings.Builder
	now := time.Now()

	b.WriteString(ufmt.Sprintf("# Quest #%d: %s\n\n", q.ID, sanitize.InlineText(q.Title)))
	b.WriteString("[← Back to the board](" + boardURL() + ")\n\n")

	b.WriteString("| Status | Reward left | Total pool | Paid out | Deadline |\n")
	b.WriteString("| :---: | :---: | :---: | :---: | :--- |\n")
	b.WriteString(ufmt.Sprintf("| **%s** | %s | %s | %s | %s |\n\n",
		statusLabel(q, now), formatGNOT(q.Remaining()), formatGNOT(q.Pool), formatGNOT(q.Paid), deadlineLabel(q, now)))

	b.WriteString("Pinned by " + userLink(q.Poster) + " " + humanDuration(now.Sub(q.CreatedAt)) + " ago. " + posterTrust(q.Poster) + "\n\n")

	if q.Details != "" {
		b.WriteString("## Details\n\n")
		b.WriteString(sanitize.Block(escapeHTML(q.Details)) + "\n\n")
	}

	if q.Status == StatusOpen {
		b.WriteString(renderActions(q, now))
	}

	b.WriteString(ufmt.Sprintf("## Hand-ins (%d)\n\n", len(q.hunters)))
	if len(q.hunters) == 0 {
		b.WriteString("*Nobody has handed in work yet.*\n\n")
	} else {
		b.WriteString("| Hunter | Proof | Handed in | Awarded |\n")
		b.WriteString("| :--- | :--- | :--- | ---: |\n")
		for _, h := range q.hunters {
			v, _ := lookup(&q.subs, h.String())
			s := v.(*Submission)
			awarded := "-"
			if s.Awarded > 0 {
				awarded = "🏆 " + formatGNOT(s.Awarded)
			}
			b.WriteString(ufmt.Sprintf("| %s | %s | %s ago | %s |\n",
				userLink(h), proofCell(s.Proof), humanDuration(now.Sub(s.At)), awarded))
		}
		b.WriteString("\n")
	}

	if len(q.Awards) > 0 {
		b.WriteString("## Awards\n\n")
		for _, a := range q.Awards {
			line := ufmt.Sprintf("- %s to %s", formatGNOT(a.Amount), userLink(a.Hunter))
			if a.Note != "" {
				line += ": " + sanitize.InlineText(a.Note)
			}
			b.WriteString(line + "\n")
		}
		b.WriteString("\n")
	}

	b.WriteString(ufmt.Sprintf("## Backers (%d)\n\n", len(q.backers)))
	for _, addr := range q.backers {
		v, _ := lookup(&q.contribs, addr.String())
		b.WriteString(ufmt.Sprintf("- %s: %s\n", userLink(addr), formatGNOT(v.(int64))))
	}
	if q.Refunded > 0 {
		b.WriteString(ufmt.Sprintf("\n%s was returned to backers when the quest settled.\n", formatGNOT(q.Refunded)))
	}
	return b.String()
}

func renderActions(q *Quest, now time.Time) string {
	var b strings.Builder
	idStr := strconv.Itoa(q.ID)
	b.WriteString("## Take part\n\n")

	if now.Before(q.Deadline) {
		b.WriteString("**Chip in to the reward:** ")
		for i, amt := range []int64{100_000, 1_000_000, 5_000_000} {
			if i > 0 {
				b.WriteString(" · ")
			}
			b.WriteString(ufmt.Sprintf("[+%s](%s)", formatGNOT(amt), board().NewLink("Fund").AddArgs("id", idStr).SetSend(ufmt.Sprintf("%dugnot", amt)).URL()))
		}
		b.WriteString("\n\n### Hand in your work\n\n")
		b.WriteString(mdform.New("exec", "Submit").
			Input("id", "value", idStr, "readonly", "true").
			Textarea("proof", "placeholder", "Link to your work, or a short note (max 280 characters)", "rows", "3").
			String())
		b.WriteString("\n\n")
	} else {
		b.WriteString("*Hand-ins are closed. The poster has until " + q.Deadline.Add(GracePeriod).UTC().Format("2006-01-02 15:04 UTC") + " to award.*\n\n")
	}

	if len(q.hunters) > 0 {
		b.WriteString("### Poster: award a hunter\n\n")
		b.WriteString("Amount is in ugnot (1 GNOT = 1000000 ugnot). Award several hunters to split the reward.\n\n")
		b.WriteString(mdform.New("exec", "Award").
			Input("id", "value", idStr, "readonly", "true").
			Input("hunter", "placeholder", "g1... address of the hunter").
			Input("amount", "type", mdform.InputTypeNumber, "value", strconv.FormatInt(q.Remaining(), 10)).
			Input("note", "placeholder", "Optional thanks or feedback").
			String())
		b.WriteString("\n\n")
	}

	b.WriteString("**Settle:** ")
	b.WriteString("[Close and refund backers (poster)](" + board().NewLink("Close").AddArgs("id", idStr).URL() + ")")
	if !now.Before(q.Deadline.Add(GracePeriod)) {
		b.WriteString(" · [Expire and refund backers (anyone)](" + board().NewLink("Expire").AddArgs("id", idStr).URL() + ")")
	}
	b.WriteString("\n\n")
	return b.String()
}

func renderProfile(addr address) string {
	var b strings.Builder
	v, ok := lookup(&profiles, addr.String())
	p := &Profile{}
	if ok {
		p = v.(*Profile)
	}
	r := rankOf(p.Wins)

	b.WriteString("# " + shortAddr(addr) + "\n\n")
	b.WriteString("[← Back to the board](" + boardURL() + ")\n\n")
	b.WriteString(badge(r, p.Wins, p.Earned) + "\n\n")
	b.WriteString("`" + addr.String() + "`\n\n")

	b.WriteString("## As a hunter\n\n")
	b.WriteString(ufmt.Sprintf("- Rank: **%s**", r.Name))
	if next := nextRank(p.Wins); next.MinWins > 0 {
		b.WriteString(ufmt.Sprintf(" (%d more win(s) to %s)", next.MinWins-p.Wins, next.Name))
	}
	b.WriteString("\n")
	b.WriteString(ufmt.Sprintf("- Hand-ins: %d\n- Quests won: %d\n- Earned: %s\n\n", p.HandIns, p.Wins, formatGNOT(p.Earned)))

	b.WriteString("## As a poster\n\n")
	b.WriteString(ufmt.Sprintf("- Quests pinned: %d\n- Settled with a payout: %d\n- Settled without a payout: %d\n- Let expire: %d\n- Paid to hunters: %s\n\n",
		p.Posted, p.Completed, p.Cancelled, p.Expired, formatGNOT(p.PaidOut)))

	b.WriteString("## As a backer\n\n")
	b.WriteString(ufmt.Sprintf("- Put into rewards: %s\n\n", formatGNOT(p.Backed)))

	var mine []*Quest
	quests.ReverseIterate("", "", func(_ string, v any) bool {
		q := v.(*Quest)
		if q.Poster == addr {
			mine = append(mine, q)
		} else if _, ok := lookup(&q.subs, addr.String()); ok {
			mine = append(mine, q)
		}
		return len(mine) >= listLimit
	})
	if len(mine) > 0 {
		b.WriteString("## Quests\n\n")
		for _, q := range mine {
			role := "hunter"
			if q.Poster == addr {
				role = "poster"
			}
			b.WriteString(ufmt.Sprintf("- [#%d %s](%s) as %s, %s\n", q.ID, sanitize.InlineText(q.Title), questURL(q.ID), role, q.Status.String()))
		}
	}
	return b.String()
}

// ----------------------------------------------------------------------------
// helpers

type hunterEntry struct {
	addr address
	p    *Profile
}

// topHunters returns the n hunters with the most GNOT earned.
func topHunters(n int) []hunterEntry {
	var top []hunterEntry
	profiles.Iterate("", "", func(k string, v any) bool {
		p := v.(*Profile)
		if p.Earned == 0 {
			return false
		}
		e := hunterEntry{address(k), p}
		i := len(top)
		for i > 0 && top[i-1].p.Earned < p.Earned {
			i--
		}
		if i < n {
			top = append(top, hunterEntry{})
			copy(top[i+1:], top[i:])
			top[i] = e
			if len(top) > n {
				top = top[:n]
			}
		}
		return false
	})
	return top
}

func awardedHunters(q *Quest) int {
	n := 0
	for _, h := range q.hunters {
		v, _ := lookup(&q.subs, h.String())
		if v.(*Submission).Awarded > 0 {
			n++
		}
	}
	return n
}

func posterTrust(addr address) string {
	v, ok := lookup(&profiles, addr.String())
	if !ok {
		return ""
	}
	p := v.(*Profile)
	settled := p.Completed + p.Cancelled
	if settled == 0 {
		return "*First quest from this poster.*"
	}
	s := ufmt.Sprintf("*Poster record: %d of %d settled quest(s) paid a hunter", p.Completed, settled)
	if p.Expired > 0 {
		s += ufmt.Sprintf(", %d left to expire", p.Expired)
	}
	return s + ".*"
}

func statusLabel(q *Quest, now time.Time) string {
	switch q.Status {
	case StatusCompleted:
		return "✅ completed"
	case StatusCancelled:
		if q.Expired {
			return "⌛ expired"
		}
		return "✖ cancelled"
	}
	if now.Before(q.Deadline) {
		return "🟢 open"
	}
	return "⏳ awaiting award"
}

func deadlineLabel(q *Quest, now time.Time) string {
	d := q.Deadline.UTC().Format("2006-01-02 15:04 UTC")
	if q.Status == StatusOpen && now.Before(q.Deadline) {
		d += " (in " + humanDuration(q.Deadline.Sub(now)) + ")"
	}
	return d
}

// proofCell renders a hand-in: http(s) links become links, anything else is
// escaped text.
func proofCell(proof string) string {
	if strings.HasPrefix(proof, "https://") || strings.HasPrefix(proof, "http://") {
		if u := sanitize.URL(proof); u != "" && !strings.ContainsAny(proof, " \t\n") {
			label := proof
			if len(label) > 48 {
				label = label[:45] + "..."
			}
			return "[" + sanitize.TableCell(label) + "](" + u + ")"
		}
	}
	return sanitize.TableCell(proof)
}

func userLink(addr address) string {
	return "[" + shortAddr(addr) + "](" + boardURL() + ":u/" + addr.String() + ")"
}

func shortAddr(addr address) string {
	s := addr.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

var (
	pkgPath   string // gno.land/r/<addr>/questboard
	boardPath string // gnoweb path, e.g. /r/<addr>/questboard
)

func init(cur realm) {
	pkgPath = cur.PkgPath()
	boardPath = strings.TrimPrefix(pkgPath, runtime.ChainDomain())
}

// board returns a txlink builder for this realm, so links point here no
// matter which realm is rendering.
func board() txlink.Realm {
	return txlink.Realm(pkgPath)
}

// escapeHTML neutralises raw HTML in user text before it is rendered as
// markdown; gnoweb shows the entities as plain characters.
func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "<", "&lt;")
	return strings.ReplaceAll(s, ">", "&gt;")
}

func boardURL() string {
	return boardPath
}

func questURL(id int) string {
	return boardURL() + ":quest/" + strconv.Itoa(id)
}

// formatGNOT renders an ugnot amount as GNOT with up to six decimals.
func formatGNOT(ugnot int64) string {
	whole := ugnot / 1_000_000
	frac := ugnot % 1_000_000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fs := strconv.FormatInt(frac, 10)
	for len(fs) < 6 {
		fs = "0" + fs
	}
	fs = strings.TrimRight(fs, "0")
	return strconv.FormatInt(whole, 10) + "." + fs + " GNOT"
}

// humanDuration renders a duration as its two largest units, e.g. "3d 4h".
func humanDuration(d time.Duration) string {
	if d < 0 {
		d = -d
	}
	day := 24 * time.Hour
	switch {
	case d >= day:
		return ufmt.Sprintf("%dd %dh", int(d/day), int((d%day)/time.Hour))
	case d >= time.Hour:
		return ufmt.Sprintf("%dh %dm", int(d/time.Hour), int((d%time.Hour)/time.Minute))
	case d >= time.Minute:
		return ufmt.Sprintf("%dm", int(d/time.Minute))
	}
	return "moments"
}

func days(d time.Duration) string {
	return strconv.Itoa(int(d/(24*time.Hour))) + " days"
}

// Package idlewatt is an on-chain registry and dashboard for idle compute
// nodes: home GPU boxes today, and someday parked vehicles, that want to rent
// spare capacity on decentralized compute networks such as Akash.
//
// IMPORTANT: every node, heartbeat and job in this realm is self-reported or
// simulated by its operator. There is no Tesla or Akash integration and no
// hardware attestation; earnings are simulated USD figures, not payments.
package idlewatt

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

// Tunables.
const (
	maxNodes             = 1000
	maxNodesPerOperator  = 10
	minHeartbeatInterval = 10 * time.Second
	poolBps              = 1400 // 14% of every job feeds the fairness pool (a nod to AtomOne's Nakamoto Bonus)
	minBonusEpoch        = time.Hour
	minOnlineWindow      = 5 * time.Minute
	maxOnlineWindow      = 7 * 24 * time.Hour
)

var (
	admin        address
	paused       bool // when true, new registrations are refused
	onlineWindow = 30 * time.Minute

	nextNodeID = 1
	nextJobID  = 1

	nodes       = avl.NewTree() // padID(nodeID) -> *Node
	byOperator  = avl.NewTree() // operator + "/" + padID -> nodeID
	leaderboard = avl.NewTree() // rankKey(total, id) -> nodeID
	jobs        = avl.NewTree() // padID(jobID) -> *Job
	nodeJobs    = avl.NewTree() // padID(nodeID) + "/" + padID(jobID) -> jobID

	totalGrossCents  int64
	poolCents        int64 // undistributed fairness pool
	poolPaidCents    int64 // distributed so far
	bonusRounds      int
	lastDistribution time.Time
)

// realmURL is this realm's gnoweb path, e.g. /r/<addr>/idlewatt.
var realmURL string

func init(cur realm) {
	admin = cur.Previous().Address()
	realmURL = strings.TrimPrefix(cur.PkgPath(), "gno.land")
}

// ---------------------------------------------------------------------------
// Operator actions. Every one of them is a signed transaction, so the
// operator address is authenticated by the chain itself.

// RegisterNode adds a node owned by the caller and returns its ID.
// kind: home-gpu | vehicle | cpu. power: grid | solar | powershare-backup.
// rateCents: asking price in US cents per hour (e.g. 45 = $0.45/h).
func RegisterNode(cur realm, name, kind, hardware, region, power string, rateCents int64) int {
	caller := mustCaller(cur)
	if paused {
		panic("registrations are paused by the realm admin")
	}
	checkText("name", name, minNameLen, maxNameLen)
	checkKind(kind)
	checkText("hardware", hardware, minNameLen, maxHardwareLen)
	checkText("region", region, minRegionLen, maxRegionLen)
	checkPower(power)
	checkRate(rateCents)
	if nodes.Size() >= maxNodes {
		panic("registry is full")
	}
	if operatorNodeCount(caller) >= maxNodesPerOperator {
		panic("an operator can register at most " + strconv.Itoa(maxNodesPerOperator) + " nodes")
	}

	now := time.Now()
	n := &Node{
		ID:           nextNodeID,
		Operator:     caller,
		Name:         name,
		Kind:         kind,
		Hardware:     hardware,
		Region:       region,
		Power:        power,
		RateCents:    rateCents,
		Mode:         ModePaused,
		RegisteredAt: now,
	}
	nextNodeID++
	nodes.Set(padID(n.ID), n)
	byOperator.Set(caller.String()+"/"+padID(n.ID), n.ID)
	leaderboard.Set(rankKey(0, n.ID), n.ID)

	chain.Emit("NodeRegistered",
		"id", strconv.Itoa(n.ID),
		"operator", caller.String(),
		"kind", kind,
		"region", region,
		"power", power,
		"rateCents", strconv.FormatInt(rateCents, 10),
	)
	return n.ID
}

// UpdateNode changes a node's descriptive fields and rate. Only the operator.
func UpdateNode(cur realm, id int, name, hardware, region, power string, rateCents int64) {
	caller := mustCaller(cur)
	n := mustOwnNode(id, caller)
	checkText("name", name, minNameLen, maxNameLen)
	checkText("hardware", hardware, minNameLen, maxHardwareLen)
	checkText("region", region, minRegionLen, maxRegionLen)
	checkPower(power)
	checkRate(rateCents)

	n.Name = name
	n.Hardware = hardware
	n.Region = region
	n.Power = power
	n.RateCents = rateCents
	chain.Emit("NodeUpdated", "id", strconv.Itoa(id), "rateCents", strconv.FormatInt(rateCents, 10))
}

// SetRate changes only the hourly asking rate (US cents). Only the operator.
func SetRate(cur realm, id int, rateCents int64) {
	caller := mustCaller(cur)
	n := mustOwnNode(id, caller)
	checkRate(rateCents)
	n.RateCents = rateCents
	chain.Emit("NodeUpdated", "id", strconv.Itoa(id), "rateCents", strconv.FormatInt(rateCents, 10))
}

// SetAvailability switches a node between available (parked & plugged in),
// driving (vehicles only) and paused. Only the operator.
func SetAvailability(cur realm, id int, mode string) {
	caller := mustCaller(cur)
	n := mustOwnNode(id, caller)
	checkMode(n.Kind, mode)
	if n.Mode == mode {
		return
	}
	prev := n.Mode
	n.Mode = mode
	chain.Emit("AvailabilityChanged", "id", strconv.Itoa(id), "from", prev, "to", mode)
}

// Heartbeat records a signed liveness ping for a node, with an optional
// short status note (e.g. "SoC 82%, 41C"). Only the operator.
func Heartbeat(cur realm, id int, note string) {
	caller := mustCaller(cur)
	n := mustOwnNode(id, caller)
	if note != "" {
		checkText("note", note, 1, maxNoteLen)
	}
	now := time.Now()
	if !n.LastHeartbeat.IsZero() {
		gap := now.Sub(n.LastHeartbeat)
		if gap < minHeartbeatInterval {
			panic("heartbeat too frequent: wait at least 10 seconds")
		}
		if gap > onlineWindow {
			n.SessionStart = now // the previous run was broken
		}
	} else {
		n.SessionStart = now
	}
	n.LastHeartbeat = now
	n.HeartbeatCount++
	n.LastNote = note
	chain.Emit("Heartbeat", "id", strconv.Itoa(id), "count", strconv.Itoa(n.HeartbeatCount))
}

// RecordJob records a completed (simulated) job on a node, e.g. an AI
// inference lease. Earnings are computed by the realm from the node's rate
// and the duration, so operators cannot claim arbitrary amounts. The node
// must be available and online. 14% of the gross goes to the fairness pool.
func RecordJob(cur realm, id int, workload string, minutes int) int {
	caller := mustCaller(cur)
	n := mustOwnNode(id, caller)
	checkText("workload", workload, minNameLen, maxWorkloadLen)
	if minutes < 1 || minutes > maxJobMinutes {
		panic("minutes must be between 1 and 1440")
	}
	if n.Mode != ModeAvailable {
		panic("node must be available (parked & plugged in) to take jobs")
	}
	now := time.Now()
	if !isOnlineAt(n, now) {
		panic("node is offline: send a heartbeat first")
	}

	gross := n.RateCents * int64(minutes) / 60
	pool := gross * poolBps / 10000
	op := gross - pool

	j := &Job{
		ID:            nextJobID,
		NodeID:        n.ID,
		NodeName:      n.Name,
		Workload:      workload,
		Minutes:       minutes,
		RateCents:     n.RateCents,
		GrossCents:    gross,
		PoolCents:     pool,
		OperatorCents: op,
		CompletedAt:   now,
	}
	nextJobID++
	jobs.Set(padID(j.ID), j)
	nodeJobs.Set(padID(n.ID)+"/"+padID(j.ID), j.ID)

	oldTotal := n.TotalCents()
	n.JobCount++
	n.JobMinutes += int64(minutes)
	n.EarnedCents += op
	reRank(n, oldTotal)

	totalGrossCents += gross
	poolCents += pool

	chain.Emit("JobRecorded",
		"job", strconv.Itoa(j.ID),
		"node", strconv.Itoa(n.ID),
		"minutes", strconv.Itoa(minutes),
		"grossCents", strconv.FormatInt(gross, 10),
		"poolCents", strconv.FormatInt(pool, 10),
		"simulated", "true",
	)
	return j.ID
}

// RemoveNode deletes the caller's node. Its job history stays on the record.
func RemoveNode(cur realm, id int) {
	caller := mustCaller(cur)
	n := mustOwnNode(id, caller)
	removeNode(n)
	chain.Emit("NodeRemoved", "id", strconv.Itoa(id), "by", "operator")
}

// DistributeBonus splits the fairness pool equally across every node that is
// online and available right now, regardless of size or earnings, like
// AtomOne's Nakamoto Bonus splits its pool equally across validators.
// Anyone may call it, at most once per hour. Returns how many nodes shared.
func DistributeBonus(cur realm) int {
	mustCaller(cur)
	now := time.Now()
	if !lastDistribution.IsZero() && now.Sub(lastDistribution) < minBonusEpoch {
		panic("the bonus can be distributed at most once per hour")
	}
	if poolCents <= 0 {
		panic("the fairness pool is empty")
	}
	var eligible []*Node
	nodes.Iterate("", "", func(_ string, v any) bool {
		n := v.(*Node)
		if n.Mode == ModeAvailable && isOnlineAt(n, now) {
			eligible = append(eligible, n)
		}
		return false
	})
	if len(eligible) == 0 {
		panic("no node is online and available to share the pool")
	}
	share := poolCents / int64(len(eligible))
	if share == 0 {
		panic("the pool is too small to split")
	}
	for _, n := range eligible {
		old := n.TotalCents()
		n.BonusCents += share
		reRank(n, old)
	}
	paid := share * int64(len(eligible))
	poolCents -= paid // the remainder stays for next round
	poolPaidCents += paid
	bonusRounds++
	lastDistribution = now
	chain.Emit("BonusDistributed",
		"round", strconv.Itoa(bonusRounds),
		"nodes", strconv.Itoa(len(eligible)),
		"shareCents", strconv.FormatInt(share, 10),
	)
	return len(eligible)
}

// ---------------------------------------------------------------------------
// Admin actions (moderation of a public demo registry).

// SetPaused stops or resumes new registrations.
func SetPaused(cur realm, p bool) {
	mustAdmin(cur)
	paused = p
	chain.Emit("PausedChanged", "paused", strconv.FormatBool(p))
}

// SetOnlineWindowMinutes sets how long after its last heartbeat a node still
// counts as online (5 minutes to 7 days).
func SetOnlineWindowMinutes(cur realm, minutes int) {
	mustAdmin(cur)
	w := time.Duration(minutes) * time.Minute
	if w < minOnlineWindow || w > maxOnlineWindow {
		panic("online window must be between 5 and 10080 minutes")
	}
	onlineWindow = w
	chain.Emit("OnlineWindowChanged", "minutes", strconv.Itoa(minutes))
}

// AdminRemoveNode removes a spam or abusive node.
func AdminRemoveNode(cur realm, id int) {
	mustAdmin(cur)
	n := mustGetNode(id)
	removeNode(n)
	chain.Emit("NodeRemoved", "id", strconv.Itoa(id), "by", "admin")
}

// TransferAdmin hands the admin role to another address.
func TransferAdmin(cur realm, newAdmin address) {
	mustAdmin(cur)
	if !newAdmin.IsValid() {
		panic("invalid address")
	}
	old := admin
	admin = newAdmin
	chain.Emit("AdminChanged", "from", old.String(), "to", newAdmin.String())
}

// ---------------------------------------------------------------------------
// Read-only helpers (safe to query with vm/qeval).

// Admin returns the admin address.
func Admin() address { return admin }

// NodeCount returns the number of registered nodes.
func NodeCount() int { return nodes.Size() }

// Stats returns nodes, online nodes, simulated gross earnings (cents) and the
// undistributed fairness pool (cents).
func Stats() (int, int, int64, int64) {
	return nodes.Size(), countOnline(time.Now()), totalGrossCents, poolCents
}

// NodeSummary returns a one-line text summary of a node, or "" if unknown.
func NodeSummary(id int) string {
	v := nodes.Get(padID(id))
	if v == nil {
		return ""
	}
	n := v.(*Node)
	return n.Name + " | " + n.Kind + " | " + n.Region + " | " + n.Power + " | " +
		fmtUSD(n.RateCents) + "/h | " + statusOf(n, time.Now()) + " | earned " + fmtUSD(n.TotalCents())
}

// ---------------------------------------------------------------------------
// internals

func mustCaller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUser() {
		panic("only user accounts can call this")
	}
	return prev.Address()
}

func mustAdmin(cur realm) {
	if mustCaller(cur) != admin {
		panic("only the admin can do this")
	}
}

func mustGetNode(id int) *Node {
	v := nodes.Get(padID(id))
	if v == nil {
		panic("node " + strconv.Itoa(id) + " not found")
	}
	return v.(*Node)
}

func mustOwnNode(id int, caller address) *Node {
	n := mustGetNode(id)
	if n.Operator != caller {
		panic("only the node's operator can do this")
	}
	return n
}

func removeNode(n *Node) {
	nodes.Remove(padID(n.ID))
	byOperator.Remove(n.Operator.String() + "/" + padID(n.ID))
	leaderboard.Remove(rankKey(n.TotalCents(), n.ID))
}

func reRank(n *Node, oldTotal int64) {
	leaderboard.Remove(rankKey(oldTotal, n.ID))
	leaderboard.Set(rankKey(n.TotalCents(), n.ID), n.ID)
}

func operatorNodeCount(op address) int {
	count := 0
	prefix := op.String() + "/"
	byOperator.Iterate(prefix, prefix+"~", func(_ string, _ any) bool {
		count++
		return false
	})
	return count
}

func isOnlineAt(n *Node, now time.Time) bool {
	if n.LastHeartbeat.IsZero() {
		return false
	}
	return now.Sub(n.LastHeartbeat) <= onlineWindow
}

func countOnline(now time.Time) int {
	count := 0
	nodes.Iterate("", "", func(_ string, v any) bool {
		if isOnlineAt(v.(*Node), now) {
			count++
		}
		return false
	})
	return count
}

// padID makes IDs sort numerically as avl keys.
func padID(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 9 {
		s = "0" + s
	}
	return s
}

// rankKey sorts the highest total first, ties broken by lowest node ID.
func rankKey(totalCents int64, id int) string {
	const ceiling = int64(999999999999999)
	inv := strconv.FormatInt(ceiling-totalCents, 10)
	for len(inv) < 15 {
		inv = "0" + inv
	}
	return inv + "/" + padID(id)
}

package idlewatt

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
)

const pageSize = 10

// Render serves the gnoweb dashboard.
//
//	""                 network summary, live node cards, leaderboard, recent jobs
//	"nodes?page=N"      every node, paginated
//	"node/<id>"         one node, its jobs and operator actions
//	"operator/<g1addr>" one operator's nodes
//	"leaderboard"       full ranking
//	"jobs?page=N"       job history
//	"about"             what this is, and what it is not
func Render(path string) string {
	route, query := path, ""
	if i := strings.Index(path, "?"); i >= 0 {
		route, query = path[:i], path[i+1:]
	}
	now := time.Now()
	switch {
	case route == "":
		return renderHome(now)
	case route == "nodes":
		return renderNodes(now, pageParam(query))
	case strings.HasPrefix(route, "node/"):
		id, err := strconv.Atoi(strings.TrimPrefix(route, "node/"))
		if err != nil {
			return notFound()
		}
		return renderNode(now, id)
	case strings.HasPrefix(route, "operator/"):
		return renderOperator(now, strings.TrimPrefix(route, "operator/"))
	case route == "leaderboard":
		return renderLeaderboard(now, 50)
	case route == "jobs":
		return renderJobs(pageParam(query))
	case route == "about":
		return renderAbout()
	}
	return notFound()
}

// ---------------------------------------------------------------------------
// pages

func renderHome(now time.Time) string {
	var b strings.Builder
	b.WriteString("# <gno-icon name=\"lightning\" /> IdleWatt\n\n")
	b.WriteString("*Idle compute, put to work.* An on-chain registry and dashboard for home GPU boxes, CPU nodes and, someday, parked vehicles that want to rent spare capacity on decentralized compute networks like Akash.\n\n")
	b.WriteString(navBar())
	b.WriteString(disclaimer())

	// Network summary cards.
	online, available, driving := 0, 0, 0
	nodes.Iterate("", "", func(_ string, v any) bool {
		n := v.(*Node)
		if isOnlineAt(n, now) {
			online++
			if n.Mode == ModeAvailable {
				available++
			}
		}
		if n.Mode == ModeDriving {
			driving++
		}
		return false
	})
	b.WriteString("## Network\n\n")
	b.WriteString("<gno-columns>\n")
	b.WriteString(statCard("server", "Nodes", strconv.Itoa(nodes.Size()), strconv.Itoa(driving)+" out driving"))
	b.WriteString("<gno-columns-sep>\n")
	b.WriteString(statCard("signal", "Online now", strconv.Itoa(online), strconv.Itoa(available)+" ready for work"))
	b.WriteString("<gno-columns-sep>\n")
	b.WriteString(statCard("coins", "Simulated earnings", fmtUSD(totalGrossCents), strconv.Itoa(jobs.Size())+" jobs recorded"))
	b.WriteString("<gno-columns-sep>\n")
	b.WriteString(statCard("trophy", "Fairness pool", fmtUSD(poolCents), fmtUSD(poolPaidCents)+" shared so far"))
	b.WriteString("</gno-columns>\n\n")

	// Node cards, highest earners first.
	b.WriteString("## Nodes\n\n")
	if nodes.Size() == 0 {
		b.WriteString("No nodes yet. Be the first to register one below.\n\n")
	} else {
		var cards []string
		leaderboard.IterateByOffset(0, 6, func(_ string, v any) bool {
			nv := nodes.Get(padID(v.(int)))
			if nv != nil {
				cards = append(cards, nodeCard(nv.(*Node), now))
			}
			return false
		})
		b.WriteString(cardGrid(cards, 3))
		if nodes.Size() > 6 {
			b.WriteString("[See all " + strconv.Itoa(nodes.Size()) + " nodes](" + link("nodes") + ")\n\n")
		}
	}

	b.WriteString("## <gno-icon name=\"trophy\" /> Leaderboard\n\n")
	b.WriteString(leaderboardTable(now, 5))
	b.WriteString("[Full leaderboard](" + link("leaderboard") + ")\n\n")

	b.WriteString("## Recent jobs\n\n")
	b.WriteString(jobsTable(0, 5, -1))
	b.WriteString("[All jobs](" + link("jobs") + ")\n\n")

	b.WriteString(bonusSection(now))
	b.WriteString(registerForm())
	return b.String()
}

func renderNodes(now time.Time, page int) string {
	var b strings.Builder
	b.WriteString("# All nodes\n\n")
	b.WriteString(navBar())
	total := nodes.Size()
	if total == 0 {
		b.WriteString("No nodes yet.\n")
		return b.String()
	}
	b.WriteString("| # | Node | Type | Region | Power | Rate | Status | Earned |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|\n")
	nodes.IterateByOffset((page-1)*pageSize, pageSize, func(_ string, v any) bool {
		n := v.(*Node)
		b.WriteString("| " + strconv.Itoa(n.ID) + " | [" + n.Name + "](" + link("node/"+strconv.Itoa(n.ID)) + ") | " +
			kindLabel(n.Kind) + " | " + n.Region + " | " + powerLabel(n.Power) + " | " + fmtUSD(n.RateCents) + "/h | " +
			statusOf(n, now) + " | " + fmtUSD(n.TotalCents()) + " |\n")
		return false
	})
	b.WriteString("\n" + pager("nodes", page, total))
	return b.String()
}

func renderNode(now time.Time, id int) string {
	v := nodes.Get(padID(id))
	if v == nil {
		return notFound()
	}
	n := v.(*Node)
	var b strings.Builder
	b.WriteString("# " + kindIcon(n.Kind) + " " + n.Name + "\n\n")
	b.WriteString(navBar())
	b.WriteString("<gno-columns>\n<gno-frame>\n")
	b.WriteString("### Status\n\n**" + statusOf(n, now) + "**\n\n")
	if n.LastHeartbeat.IsZero() {
		b.WriteString("No heartbeat yet.\n\n")
	} else {
		b.WriteString("Last heartbeat " + ago(now.Sub(n.LastHeartbeat)) + " (" + strconv.Itoa(n.HeartbeatCount) + " total)\n\n")
		if isOnlineAt(n, now) && n.LastHeartbeat.Sub(n.SessionStart) >= time.Minute {
			b.WriteString("Up for " + fmtDuration(n.LastHeartbeat.Sub(n.SessionStart)) + "\n\n")
		}
		if n.LastNote != "" {
			b.WriteString("Note: *" + n.LastNote + "*\n\n")
		}
	}
	b.WriteString("</gno-frame>\n<gno-columns-sep>\n<gno-frame>\n")
	b.WriteString("### Specs\n\n")
	b.WriteString("- Type: " + kindLabel(n.Kind) + "\n")
	b.WriteString("- Hardware: " + n.Hardware + "\n")
	b.WriteString("- Region: " + n.Region + "\n")
	b.WriteString("- Power: " + powerLabel(n.Power) + "\n")
	b.WriteString("- Rate: **" + fmtUSD(n.RateCents) + "/hour**\n\n")
	b.WriteString("</gno-frame>\n<gno-columns-sep>\n<gno-frame>\n")
	b.WriteString("### Earnings (simulated)\n\n")
	b.WriteString("- Jobs: " + strconv.Itoa(n.JobCount) + " (" + fmtDuration(time.Duration(n.JobMinutes)*time.Minute) + " of compute)\n")
	b.WriteString("- From jobs: " + fmtUSD(n.EarnedCents) + "\n")
	b.WriteString("- Fairness bonus: " + fmtUSD(n.BonusCents) + "\n")
	b.WriteString("- **Total: " + fmtUSD(n.TotalCents()) + "**\n")
	b.WriteString("- Rank: #" + strconv.Itoa(rankOf(n)) + " of " + strconv.Itoa(nodes.Size()) + "\n\n")
	b.WriteString("</gno-frame>\n</gno-columns>\n\n")

	b.WriteString("Operator: [" + shortAddr(n.Operator) + "](" + link("operator/"+n.Operator.String()) + ") · registered " + n.RegisteredAt.UTC().Format("Jan 2, 2006") + "\n\n")

	b.WriteString("## Operator actions\n\n")
	b.WriteString("Only this node's operator (" + shortAddr(n.Operator) + ") can sign these. Each button opens a prefilled transaction form.\n\n")
	sid := strconv.Itoa(n.ID)
	b.WriteString("<gno-button href=\"" + txlink.NewLink("Heartbeat").AddArgs("id", sid, "note", "").URL() + "\" label=\"Send heartbeat\" />\n")
	b.WriteString("<gno-button href=\"" + txlink.NewLink("SetAvailability").AddArgs("id", sid, "mode", ModeAvailable).URL() + "\" label=\"Parked and plugged in\" variant=\"success\" />\n")
	if n.Kind == KindVehicle {
		b.WriteString("<gno-button href=\"" + txlink.NewLink("SetAvailability").AddArgs("id", sid, "mode", ModeDriving).URL() + "\" label=\"Driving\" variant=\"warning\" />\n")
	}
	b.WriteString("<gno-button href=\"" + txlink.NewLink("SetAvailability").AddArgs("id", sid, "mode", ModePaused).URL() + "\" label=\"Pause\" variant=\"outline\" />\n")
	b.WriteString("<gno-button href=\"" + txlink.NewLink("RecordJob").AddArgs("id", sid, "workload", "llama-3.3-70b inference", "minutes", "60").URL() + "\" label=\"Record a simulated job\" variant=\"info\" />\n")
	b.WriteString("<gno-button href=\"" + txlink.NewLink("SetRate").AddArgs("id", sid, "rateCents", strconv.FormatInt(n.RateCents, 10)).URL() + "\" label=\"Change rate\" variant=\"outline\" />\n\n")

	b.WriteString("## Job history\n\n")
	b.WriteString(jobsTable(0, 20, n.ID))
	return b.String()
}

func renderOperator(now time.Time, addr string) string {
	var b strings.Builder
	b.WriteString("# Operator " + safeAddrText(addr) + "\n\n")
	b.WriteString(navBar())
	var cards []string
	prefix := addr + "/"
	byOperator.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		nv := nodes.Get(padID(v.(int)))
		if nv != nil {
			cards = append(cards, nodeCard(nv.(*Node), now))
		}
		return false
	})
	if len(cards) == 0 {
		b.WriteString("This address has no nodes.\n")
		return b.String()
	}
	b.WriteString(cardGrid(cards, 3))
	return b.String()
}

func renderLeaderboard(now time.Time, limit int) string {
