func pageParam(query string) int {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			p, err := strconv.Atoi(strings.TrimPrefix(kv, "page="))
			if err == nil && p >= 1 && p <= 100000 {
				return p
			}
		}
	}
	return 1
}

