func boolWord(b bool, yes, no string) string {
	if b {
		return yes
	}
	return no
}

// fmtUSD renders cents as $1,234.56.
func fmtUSD(cents int64) string {
	neg := cents < 0
	if neg {
		cents = -cents
	}
	whole := strconv.FormatInt(cents/100, 10)
	frac := strconv.FormatInt(cents%100, 10)
	if len(frac) < 2 {
		frac = "0" + frac
	}
	for i := len(whole) - 3; i > 0; i -= 3 {
		whole = whole[:i] + "," + whole[i:]
	}
	out := "$" + whole + "." + frac
	if neg {
		out = "-" + out
	}
	return out
}

func fmtDuration(d time.Duration) string {
	if d < time.Minute {
		return strconv.Itoa(int(d/time.Second)) + "s"
	}
	mins := int(d / time.Minute)
	if mins < 60 {
		return strconv.Itoa(mins) + "m"
	}
	h, m := mins/60, mins%60
	if h < 48 {
		if m == 0 {
			return strconv.Itoa(h) + "h"
		}
		return strconv.Itoa(h) + "h " + strconv.Itoa(m) + "m"
	}
	return strconv.Itoa(h/24) + "d " + strconv.Itoa(h%24) + "h"
}

func ago(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	return fmtDuration(d) + " ago"
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// safeAddrText echoes a user-supplied path segment only if it looks like an
// address, so the page never reflects arbitrary markdown.
func safeAddrText(s string) string {
	if address(s).IsValid() {
		return shortAddr(address(s))
	}
	return "(invalid address)"
}

func plural(n int, word string) string {
	if n == 1 {
		return "1 " + word
	}
	return strconv.Itoa(n) + " " + word + "s"
}

package idlewatt

import "time"

// Node kinds.
const (
	KindHomeGPU = "home-gpu"
	KindVehicle = "vehicle"
	KindCPU     = "cpu"
)

// Power sources.
const (
	PowerGrid       = "grid"
	PowerSolar      = "solar"
	PowerPowershare = "powershare-backup"
)

// Availability modes.
const (
	ModeAvailable = "available" // parked & plugged in, ready for work
	ModeDriving   = "driving"   // vehicle in use, not renting compute
	ModePaused    = "paused"    // operator paused the node
)

// Node is one idle-compute node registered by an operator.
// All figures are self-reported by the operator; nothing here is verified
// by Akash, Tesla or any hardware attestation (yet).
type Node struct {
	ID        int
	Operator  address
	Name      string
	Kind      string
	Hardware  string
	Region    string
	Power     string
	RateCents int64 // asking price, USD cents per hour
	Mode      string

	RegisteredAt   time.Time
	LastHeartbeat  time.Time // zero if never
	SessionStart   time.Time // start of the current unbroken heartbeat run
	HeartbeatCount int
	LastNote       string

	JobCount    int
	JobMinutes  int64
	EarnedCents int64 // operator share of simulated job earnings
	BonusCents  int64 // share of the small-node fairness pool
}

// TotalCents is what the leaderboard ranks on.
func (n *Node) TotalCents() int64 {
	return n.EarnedCents + n.BonusCents
}

// Job is one simulated (self-reported) lease / job completion.
type Job struct {
	ID            int
	NodeID        int
	NodeName      string // snapshot, survives node removal
	Workload      string
	Minutes       int
	RateCents     int64
	GrossCents    int64 // rate x duration
	PoolCents     int64 // part sent to the fairness pool
	OperatorCents int64
	CompletedAt   time.Time
}

package idlewatt

import "strconv"

// Input limits.
const (
	minNameLen     = 3
	maxNameLen     = 48
	maxHardwareLen = 80
	minRegionLen   = 2
	maxRegionLen   = 40
	maxWorkloadLen = 60
	maxNoteLen     = 60
	maxRateCents   = 100000 // $1,000/hour sanity cap
	maxJobMinutes  = 24 * 60
)

// isSafeChar is the character whitelist for every free-text field. It keeps
// operator-supplied strings from injecting markdown, HTML, gnoweb tags or
// table pipes into Render output, and keeps them single-line.
func isSafeChar(c rune) bool {
	switch {
	case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		return true
	}
	switch c {
	case ' ', '-', '.', ',', '(', ')', '\'', '/', '+', ':', '@', '#', '%', '&', '=':
		return true
	}
	return false
}

// checkText validates a free-text field and panics with a readable message.
func checkText(field, s string, minLen, maxLen int) {
	if len(s) < minLen || len(s) > maxLen {
		panic(field + " must be " + strconv.Itoa(minLen) + "-" + strconv.Itoa(maxLen) + " characters")
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		panic(field + " must not start or end with a space")
	}
	for _, c := range s {
		if !isSafeChar(c) {
			panic(field + " contains an unsupported character: only letters, digits, spaces and - . , ( ) ' / + : @ # % & = are allowed")
		}
	}
}

func checkKind(kind string) {
	switch kind {
	case KindHomeGPU, KindVehicle, KindCPU:
		return
	}
	panic("kind must be one of: home-gpu, vehicle, cpu")
}

func checkPower(power string) {
	switch power {
	case PowerGrid, PowerSolar, PowerPowershare:
		return
	}
	panic("power must be one of: grid, solar, powershare-backup")
}

func checkRate(rate int64) {
	if rate < 1 || rate > maxRateCents {
		panic("rate must be between 1 and " + strconv.Itoa(maxRateCents) + " US cents per hour")
	}
}

func checkMode(kind, mode string) {
	switch mode {
	case ModeAvailable, ModePaused:
		return
	case ModeDriving:
		if kind != KindVehicle {
			panic("only vehicle nodes can be set to driving")
		}
		return
	}
	panic("mode must be one of: available, driving, paused")
}
